WordHunterWoW_QuestEN = WordHunterWoW_QuestEN or {}
WordHunterWoW_QuestEN[61786] = { title = "Adventurer: Stonehead", description = "", objectives = "Your \"good bud\" Stonehead insists on fighting for the cause, <name>.\n\nI'm sure we can find a use for his skills. Nothing too complicated, of course." }
WordHunterWoW_QuestEN[61787] = { title = "Micro Defense Force", description = "", objectives = "Defeat Grixis Tinypop in a pet battle." }
WordHunterWoW_QuestEN[61788] = { title = "Adventurer: Simone", description = "", objectives = "Your actions on behalf of Revendreth are garnering quite a lot of attention, <name>.\n\nSimone has offered to lend her expertise with the mirrors of the Ember Ward to the cause." }
WordHunterWoW_QuestEN[61789] = { title = "Adventurer: Lost Sybille", description = "", objectives = "Lost Sybille comes highly recommended by Theotar.\n\nPlus, she dropped a bag of Stone Legion heads and two canisters of anima on our doorstep when she arrived. So I guess she's fighting for us already.\n\nLet's see what she can do with some allies." }
WordHunterWoW_QuestEN[61790] = { title = "Adventurer: Vulca", description = "", objectives = "Anyone that survives in the Ember Ward as long as Vulca did is tough as stone.\n\nShe'll have an unexpected trick or two to help us take down the enemy." }
WordHunterWoW_QuestEN[61791] = { title = "Thenia's Loyal Companions", description = "", objectives = "Defeat Grixis Tinypop in a pet battle." }
WordHunterWoW_QuestEN[61792] = { title = "Adventurer: Bogdan", description = "", objectives = "Your loyalty to Revendreth is unquestionable, <name>.\n\nBogdan has offered to take a leave of absence from Theotar's service, and will assist you however he can." }
WordHunterWoW_QuestEN[61813] = { title = "Valinor, the Light of Eons", description = "", objectives = "" }
WordHunterWoW_QuestEN[61814] = { title = "Nurgash Muckformed", description = "", objectives = "" }
WordHunterWoW_QuestEN[61815] = { title = "Oranomonos the Everbranching", description = "", objectives = "" }
WordHunterWoW_QuestEN[61816] = { title = "Mortanis", description = "", objectives = "" }
WordHunterWoW_QuestEN[61839] = { title = "Nipping at the Undergrowth", description = "<The small gorger nips at your heels hungry and seeking your protection. Maybe it will like some of the plants here?>", objectives = "Collect Endmire Vineroot.", progress = "Collect Endmire Vineroot for your small gorger.", completion = "<The gorger munches loudly on the vineroot and in between mouthfuls looks at you inquisitively.>" }
WordHunterWoW_QuestEN[61840] = { title = "Vineroot on the Menu", description = "<Again the small gorger shows up and you can clearly see is looking for more Endmire Vineroot.>", objectives = "Collect Endmire Vineroot.", progress = "Collect Endmire Vineroot for your small gorger.", completion = "<You barely get your hand back as the gorger snags the bundle. You can't help but notice he looks to be getting bigger. In between bites he spits out something.>" }
WordHunterWoW_QuestEN[61841] = { title = "Not Much to Goo On", description = "", objectives = "" }
WordHunterWoW_QuestEN[61842] = { title = "Vineroot Will Not Do", description = "<Clearly bigger, the gorger looks at a vineroot you point to and you can see the hint of menace in its eye at being offered the root again. It looks longingly at the devourer mites nearby.>", objectives = "Collect Infused Endmire Fruit.", progress = "Collect Infused Endmire Fruit from the Devourer Mites in the Endmire or Banewood.", completion = "<When you drop the fruit at the feet of the gorger he devourers each one whole,  clearly it is enjoying them. Looking at you not eating it lets a couple fall for you.>" }
WordHunterWoW_QuestEN[61844] = { title = "Hungry Hungry Gorger", description = "<The gorger spawn bounded up to you, but was clearly looking at the devourer mites the entire time.>", objectives = "Collect Infused Endmire Fruit.", progress = "Collect Infused Endmire Fruit from the Devourer Mites in the Endmire or Banewood.", completion = "<As you drop the fruit the gorger snaps some out of the air before they hit the ground. But you do see that the gorger has brought you a small item.>" }
WordHunterWoW_QuestEN[61845] = { title = "Edict of Doom: Devourers", description = "The infusion of anima within Revendreth has led to a resurgence in devourer infestations. These eaters of the world must be slain.\n\nBy order of Prince Renathal and the rightful Court of Harvesters, this edict decrees the doom upon these aberrations.\n\nComplete this quota of destruction within Revendreth and receive a reward equal to your efforts.", objectives = "Destroy 20 Devourers in Revendreth.", completion = "Devourers. Filthy aberrations. We should have recognized their coming as the sign of the end times that they were.\n\nYou have our gratitude, Maw Walker." }
WordHunterWoW_QuestEN[61846] = { title = "Edict of Doom: Dredbats", description = "The recent suffusion of anima in the region has led to an increase in dredbats being animated far and above any intended volume.\n\nBy order of Prince Renathal and the true Court of Harvesters an edict of doom is declared on dredbats within Revendreth. \n\nAvoid those used for transport or assigned to specific duties, but slay any in the less tamed regions of the realm and a reward shall be proffered.", objectives = "Destroy 25 Dredbats in Revendreth.", progress = "Maw Walker?", completion = "Ah, well done. Dredbats are useful entities when they serve their intended purpose. Left unchecked and untamed, however, they become competing predators for what few souls remain in our care." }
WordHunterWoW_QuestEN[61847] = { title = "Overdue Purging", description = "There are many duties of a stoneborn that have been forsaken by the plans of Denathrius. \n\nOne such duty is the elimination of manifestations. The process venthyr use to extract anima from souls is not clean, and often leads to unresolved issues made manifest. \n\nThese entities are dangerous if left unchecked, and increase in number thanks to your revivication of anima to these droughted lands.\n\nWhile you patrol Revendreth, destroy any manifestations you encounter and I shall provide you recompense.", objectives = "Destroy 30 Manifestations in Revendreth.", completion = "Your efforts are much appreciated. \n\nWhen this conflict is over, the Stone Legion should once again return to its noble purpose of protecting Revendreth, instead of satisfying the dark whims of Denathrius and his allies." }
WordHunterWoW_QuestEN[61848] = { title = "Edict of Doom: Sinstone Golems", description = "By order of the true Court of Harvesters an edict of doom is issued for any Sinstone Golems that have coalesced into dangerous sizes within the realm. \n\nThese entities are the manifestation of unresolved sins of those souls who failed their redemption and were condemned to the Maw. With the recent suffusion of anima to the region they have grown dangerously strong.\n\nExpunge them from existence and recompense shall be provided.", objectives = "Destroy 4 Sinstone Golems in Revendreth.", completion = "You do the work the Stone Legion was once tasked to accomplish in better times. You have our gratitude." }
WordHunterWoW_QuestEN[61849] = { title = "Take the Bite Out of 'Em", description = "Right. So you got a quota of venthyr you need offed and I got a mean need for some payback.\n\nSee, you may not think it to look at me but 'em venthyr loooove to chew on me specifically. Not sure what dark habit followed them across the veil but I just was a squishy bag of indulgence for far too long.\n\nAs you go about offin' 'em venthyr for your normal... motivations... I'd ask you to bring me a bunch of fangs off 'em you off, as it were. \n\nI'll pay for payback!", objectives = "Collect 40 Venthyr Fangs.", progress = "I'm gettin' quite a collection goin'.", completion = "Much obliged. This will go a long way to servin' \"restitutions\" as 'em fang heads would say." }
WordHunterWoW_QuestEN[61851] = { title = "Shades of Muck", description = "Yeah, this here muck pool's got everythin' we need to make your dredger butler.\n\nWe'll make this one special just for you. Made to specifications, as the fangs say.\n\nFirst up, you gotta choose its color. Us dredgers comes in all kind of different shades of muck.\n\nTake a peek at some me fellow dredgers and let me know what color we should dredge up for your butler.\n\nWe can recolor a dredger after-the-fact, but it ain't pleasant.\n\n<Rendle shudders at the thought.>", objectives = "Look at nearby dredgers to see color options, and then tell Rendle which color you want.", progress = "What color you thinkin' of?", completion = "I'll get the pigment all ready for you, but we're gonna need a little something extra for this dredger mucking." }
WordHunterWoW_QuestEN[61852] = { title = "Adventurer: Guardian Kota", description = "", objectives = "Hello again, <name>. It is good to see you taking such an active interest in the affairs of Ardenweald.\n\nThe honorable Guardian Kota has agreed to work with us, as part of her duties to protect the grove of Tirna Vaal.\n\nTogether, you will ensure the forest's continued security." }
WordHunterWoW_QuestEN[61853] = { title = "Adventurer: Te'zan", description = "", objectives = "The forest is ever in need, <name>.\n\nTe'zan is as spirited as ever, and perhaps a healthy dose of responsibility will lend him some direction and meaning to his afterlife.\n\nWhere should we send him first?" }
WordHunterWoW_QuestEN[61854] = { title = "Adventurer: Master Sha'lor", description = "", objectives = "The forest blesses us today, <name>.\n\nMaster Sha'lor says he has sufficiently recovered from his ordeal with the gorm, and would like to be of assistance however he can. He seems especially eager to learn new things.\n\nI guess a little taste of adventure goes a long way." }
WordHunterWoW_QuestEN[61855] = { title = "Adventurer: Qadarin", description = "", objectives = "Good to see you again, <name>.\n\nYour continued dedication to the well-being of Ardenweald has not gone unnoticed.\n\nQadarin has expressed interest in taking a more active role. Let's put his skills to use, shall we?" }
WordHunterWoW_QuestEN[61856] = { title = "Adventurer: Watcher Vesperbloom", description = "", objectives = "I have a particularly special boon for you, o' champion of Ardenweald. Are you ready?\n\nThe individual joining our Hunt today is... me!\n\n<Vesperbloom rubs her hands together, grinning.>\n\nIt will be nice to get in some field work!" }
WordHunterWoW_QuestEN[61857] = { title = "Adventurer: Groonoomcrooek", description = "", objectives = "<name>, your devotion to Ardenweald, and to the Queen, is unquestionable.\n\nSomething you've done seems to have satisfied Groonoomcrooek. I'm not sure exactly what it was, though.\n\nIt took them a while just to tell me they would be joining us here." }
WordHunterWoW_QuestEN[61859] = { title = "Adventurer: Nemea", description = "", objectives = "It is good to see you again, <name>.\n\nA friend of yours has kindly offered to assist in our endeavors here: Nemea, the larion master. She will be a powerful ally." }
WordHunterWoW_QuestEN[61860] = { title = "Adventurer: Pelodis", description = "", objectives = "It is good to see you again, <name>.\n\nA friend of yours has kindly offered to assist in our endeavors here: Pelodis, the phalynx master. He will be a powerful ally." }
WordHunterWoW_QuestEN[61861] = { title = "Adventurer: Sika", description = "", objectives = "It seems we have another recruit, <name>.\n\nSika has asked to aid us here whenever she is not tending to her duties at the Eternal Forge.\n\nDo not underestimate her worth as an ally!" }
WordHunterWoW_QuestEN[61862] = { title = "Adventurer: Clora", description = "", objectives = "<name>, I would ask for a moment of your time.\n\nOne of the recently ascended, Clora, feels that her fierce combat skills would be best put to use tackling the matters laid out before us. I am inclined to agree." }
WordHunterWoW_QuestEN[61863] = { title = "Adventurer: Apolon", description = "", objectives = "Hello there, my mortal friend! I have good news for you today.\n\nApolon has told me with great certainty that the path he follows is intertwined with yours.\n\nThough he has duties to the Path of Ascension, his courage will be of great aid to us here as well." }
WordHunterWoW_QuestEN[61864] = { title = "Adventurer: Bron", description = "", objectives = "Mikanikos has made a sensible suggestion, <name>.\n\nWhen Bron is not directly assisting you in the field, he could be of service elsewhere throughout the Shadowlands.\n\nI am sure Bron will not mind." }
WordHunterWoW_QuestEN[61865] = { title = "Adventurer: Disciple Kosmas", description = "", objectives = "Your dedication to Bastion is inspiring, <name>.\n\nWith the anima you have returned to us, Disciple Kosmas feels he can be away from the Temple of Purity for a time.\n\nHe has offered to join us here at the Hold, and contribute to the greater needs of the Shadowlands." }
WordHunterWoW_QuestEN[61866] = { title = "Mighty Minions of Maldraxxus", description = "", objectives = "Defeat Grixis Tinypop in a pet battle." }
WordHunterWoW_QuestEN[61867] = { title = "Extra Pieces", description = "", objectives = "Defeat Grixis Tinypop in a pet battle." }
WordHunterWoW_QuestEN[61868] = { title = "Uncomfortably Undercover", description = "", objectives = "Defeat Grixis Tinypop in a pet battle." }
WordHunterWoW_QuestEN[61869] = { title = "Search the Place", description = "Zerekriss is ours... along with everything it contains.\n\nThe Primus was personally involved in the design of this necropolis. It was truly a sight to witness his hands shape the form of this vessel.\n\nIt would be wise to search the room. Perhaps he kept some tools here that might be of use to us.", objectives = "Check the Foreman's Chest for anything valuable.", progress = "What did you find?", completion = "These belonged to the Primus!" }
WordHunterWoW_QuestEN[61870] = { title = "Failed Experiment", description = "", objectives = "Defeat Grixis Tinypop in a pet battle." }
WordHunterWoW_QuestEN[61871] = { title = "To Current Matters", description = "Ye've done good here, champion. MOTHER and I will be figurin' out what te do next.\n\nYe best get back te matters at hand, and do what ye can te empower that necklace o' yours.\n\nI've got ways te reach ye once MOTHER and I have fixed things up here.", objectives = "Return to Nathanos Blightcaller on the Banshee's Wail in Zuldazar.", completion = "You're back. I suppose there's something around here for you to do." }
WordHunterWoW_QuestEN[61872] = { title = "To Current Matters", description = "Ye've done good here, champion. MOTHER and I will be figurin' out what te do next.\n\nYe best get back te matters at hand, and do what ye can te empower that necklace o' yours.\n\nI've got ways te reach ye once MOTHER and I have fixed things up here.", objectives = "Return to Halford Wyrmbane on the Wind's Redemption in Boralus.", completion = "<name>, it is good to see you again. There's much to do around here." }
WordHunterWoW_QuestEN[61874] = { title = "Shadowlands: A Chilling Summons", description = "The time has come, {class}.\n\nHighlord Bolvar Fordragon requests your presence atop Icecrown Citadel. Meet me in Orgrimmar, and I will take you to him.\n\nI would not keep him waiting.", objectives = "Meet Darion Mograine outside Grommash Hold in Orgrimmar.", completion = "It is good that you have arrived.\n\nWe need heroes like you in this dire hour." }
WordHunterWoW_QuestEN[61875] = { title = "Doing the Dew", description = "The Thistledrop is magnificent creature. The roots go deep into the earth where they drink of waters most ancient. With these waters they collect the very essence of the land into a drop of dew that enables our artisans to craft powerful armaments.\n\nHelp us gather the dew and you will be well rewarded.\n\nHurry, before it evaporates!", objectives = "Collect 30 Thistledrop Dew in Ardenweald's Forests.", progress = "The dew evaporates quickly, hurry now!", completion = "This dew will help our craftmasters a great deal!\n\nThank you, little one." }
WordHunterWoW_QuestEN[61876] = { title = "Take Heart", description = "Mograine and I spoke at length when he visited Bastion. He suggested that should we manage to kill Gharmal, his heart could be used to empower the Crest of Ascension.\n\nThe Margrave bears the power to shape form in ways few beings can. Though his results are grim, if we could harness that power our Ascended would be stronger than ever before.\n\nIt is not our way, but our way is changing, I think. Perhaps this is a step on our new path.", objectives = "Collect the Fleshshaper's Heart.", progress = "It must be done.", completion = "I am relieved that I am not the one to carry that thing back to Bastion." }
WordHunterWoW_QuestEN[61877] = { title = "Return to the Hold", description = "Let us ferry the heart to Elysian Hold swiftly.\n\nThere are many in the Shadowlands who would strike at us to take its power for their own. Keep your eyes open, Maw Walker.\n\nWe return to our kin victorious this day.", objectives = "Meet Xandria at the Crest of Ascension in Elysian Hold in Bastion.", completion = "I am glad to be among our own once more. Maldraxxus is not to my tastes." }
WordHunterWoW_QuestEN[61878] = { title = "Crest of Greatness", description = "Once you are ready, all you must do is place the heart within the sphere here on the Crest of Ascension.\n\nMikanikos's handiwork will ensure that its energy is channeled properly to aid in our ascension rituals, and its power should help protect the Crest against any further attack.\n\nMay the House of Constructs never set foot in our realm again.", objectives = "Place the Fleshshaper's Heart in the Crest of Ascension.", progress = "<This looks to be the orb Xandria directed you to place the heart in.>", completion = "<The Fleshshaper's Heart fits readily into the glowing sphere. As it enters, you hear faint clicking sounds within the Crest, as if it were designed to accept such power readily.\n\nThus begins a new era for the kyrian.>" }
WordHunterWoW_QuestEN[61879] = { title = "Ashes Will Fall", description = "", objectives = "Defeat Grixis Tinypop in a pet battle." }
WordHunterWoW_QuestEN[61880] = { title = "Honored Attendance", description = "It is my humble honor to be the Ember Court's first guest.\n\nPlease inform Prince Renathal and all of your other compatriots that I will certainly attend whenever you wish to open the gates.", objectives = "Inform Temel that Cryptkeeper Kassir will attend the Ember Court.", completion = "If Kassir is coming, we had better ensure this is a formal affair." }
WordHunterWoW_QuestEN[61882] = { title = "Formal Entertainment", description = "The Accuser will be pleased that you have chosen such humble and formal entertainment for the first Ember Court.\n\nI look forward to the occasion.", objectives = "Inform Temel that you have secured entertainment for the Ember Court.", completion = "Ancient rituals? This is my kind of party!" }
WordHunterWoW_QuestEN[61883] = { title = "Resilient Survivors", description = "", objectives = "Defeat Grixis Tinypop in a pet battle." }
WordHunterWoW_QuestEN[61884] = { title = "Formal Refreshments", description = "Tubbins's tea ready soon. Go tell Theotar and friends.\n\nTubbins is best!", objectives = "Inform Temel that you have secured refreshments for the Ember Court.", completion = "Tubbins had better bring Gubbins along. He's the fun one!" }
WordHunterWoW_QuestEN[61885] = { title = "Eyegor's Special Friends", description = "", objectives = "Defeat Grixis Tinypop in a pet battle." }
WordHunterWoW_QuestEN[61886] = { title = "The Mind Games of Addius", description = "", objectives = "Defeat Grixis Tinypop in a pet battle." }
WordHunterWoW_QuestEN[61892] = { title = "Ember Court Ambassador", description = "Expanding your influence is quite simple.\n\nFind someone. Ask them what they want. Give it to them.\n\nCongratulations. You now have influence with them.\n\nIf we wish to engage the other realms and win them over to our side, we must do the same on a larger scale.\n\nSo go to the other realms. Give them what they want. Expand our influence.", objectives = "Complete World Quests across the Shadowlands.", completion = "Our contacts in the other realms have already reported positive chatter surrounding your actions there.\n\n<Lady Ilinca smiles.>\n\nOur influence grows." }
WordHunterWoW_QuestEN[61893] = { title = "Ember Court Ambassador", description = "Expanding your influence is quite simple.\n\nFind someone. Ask them what they want. Give it to them.\n\nCongratulations. You now have influence with them.\n\nIf we wish to engage the other realms and win them over to our side, we must do the same on a larger scale.\n\nSo go to the other realms. Give them what they want. Expand our influence.", objectives = "Complete World Quests across the Shadowlands.", completion = "Our contacts in the other realms have already reported positive chatter surrounding your actions there.\n\n<Lady Ilinca smiles.>\n\nOur influence grows." }
WordHunterWoW_QuestEN[61894] = { title = "Ember Court Ambassador", description = "Expanding your influence is quite simple.\n\nFind someone. Ask them what they want. Give it to them.\n\nCongratulations. You now have influence with them.\n\nIf we wish to engage the other realms and win them over to our side, we must do the same on a larger scale.\n\nSo go to the other realms. Give them what they want. Expand our influence.", objectives = "Complete World Quests across the Shadowlands.", completion = "Our contacts in the other realms have already reported positive chatter surrounding your actions there.\n\n<Lady Ilinca smiles.>\n\nOur influence grows." }
WordHunterWoW_QuestEN[61895] = { title = "Ember Court Ambassador", description = "Expanding your influence is quite simple.\n\nFind someone. Ask them what they want. Give it to them.\n\nCongratulations. You now have influence with them.\n\nIf we wish to engage the other realms and win them over to our side, we must do the same on a larger scale.\n\nSo go to the other realms. Give them what they want. Expand our influence.", objectives = "Complete World Quests across the Shadowlands.", completion = "Our contacts in the other realms have already reported positive chatter surrounding your actions there.\n\n<Lady Ilinca smiles.>\n\nOur influence grows." }
WordHunterWoW_QuestEN[61896] = { title = "Undercover Security", description = "Do you know why the venthyr carve stoneborn into different shapes?\n\nBecause diversity in form allows for diversity in strategy. Our different shapes give us different purpose.\n\nWe need a new shape to solidify our court defenses.\n\nWith the right training and tools, venthyr guards could be hidden in plain sight--posed as greeters.\n\nAble to be among the guests without raising concerns, they'd be the first to respond to active threats.", objectives = "Collect The Everyday Assassin training guide from Maldraxxus and 20 Enchanted Trickster Dust from Ardenweald.", progress = "Undercover guards? Interesting idea...", completion = "This was the easy part. The hard part will be finding guards who want to listen to socialites prattle for hours on end." }
WordHunterWoW_QuestEN[61898] = { title = "Small Bites", description = "The reviews are in, {name}. Our menu is too Revendreth-centric!\n\nAll the best courts have exotic appetizers, small plates, and other specialties that guests can look forward to every time they come.\n\nAnd for a court like ours, which boasts frequent guests from other realms, we simply must do better!\n\nDo not worry, after tireless research, I have drafted a very particular list of ingredients for you to find me.\n\nBring them to me, and I will serve our guests eternity on a platter!", objectives = "Collect cheeses from Bastion and Sourbread Yeast Starter from Maldraxxus.", progress = "Are you sure Picky Stefan wanted ALL of these things?", completion = "I never understand you mortals' fascination with cheese... It looks disgusting.\n\nBut Picky Stefan gets what Picky Stefan wants!" }
WordHunterWoW_QuestEN[61899] = { title = "Anima Tastings", description = "You started a trend, {name}!\n\nYour constant gallivanting around the different realms of the Shadowlands has inspired a new flair for the exotic among Revendreth's elite. If it's from outside Revendreth, the venthyr want to try it.\n\nAnd I know just what the next big thing will be: anima tastings!\n\nThink about it: we--and by 'we' I mean 'you'--bring back fresh anima from all the different realms you travel to.\n\nThen socialites get to sip it and pretend it tastes like wherever you got it from!", objectives = "Collect fresh anima from Ardenweald, Bastion, Maldraxxus, and Revendreth.", progress = "That's a whole lot of anima you got there. That's all just for drinking?", completion = "Hips already sent over a name for the Master of Anima he wants to lead the tastings.\n\nI'll get her on the staff and have this stuff delivered to her." }
WordHunterWoW_QuestEN[61900] = { title = "Comfy Chairs", description = "I want guests to sit.\n\nStanding is hard. I know 'cause I stand a lot.\n\nGuest should sit and be comfy.\n\nI make comfy chairs for all guests to sit.\n\nGuests be happy, stay longer!", objectives = "Collect 30 Soft Vulpin Fur from Bastion and 30 Reclaimed Wood from Ardenweald.", progress = "Boot knows his stuff. If he says we should make chairs, we should make chairs.", completion = "<Temel can't stop himself from feeling the soft vulpin fur.>\n\nOoo, these chairs are going to be so comfortable!" }
WordHunterWoW_QuestEN[61916] = { title = "Restock: Fire Damage", description = "", objectives = "Decorations not ready!\n\nLast Ember Court, those big fires from candles burn all the tablecloths.\n\nBring me pretty cloth and I make new tablecloths.\n\nThen we can pick decorations for next court.", progress = "Decorations not ready!\n\nLast Ember Court, those big fires from candles burn all the tablecloths.\n\nBring me pretty cloth and I make new tablecloths.\n\nThen we can pick decorations for next court.", completion = "This good cloth. Will dip in muck to make fire-proof.\n\nDecorations be ready for you now!" }
WordHunterWoW_QuestEN[61943] = { title = "Court Influencer", description = "", objectives = "Your investments into the Ember Court have allowed me to compile this list of potential new guests we could invite.\n\nPlease, browse them at your convenience and inform me who we should extend an invitation to first." }
WordHunterWoW_QuestEN[61944] = { title = "Discerning Taste", description = "", objectives = "Your investments into the Ember Court have attracted the attention of some very powerful individuals, <name>.\n\nI have compiled a list of these exclusive guests. Review them at your convenience and inform me who you wish to extend an invitation to first.\n\nFair warning, these discerning individuals will not be as easy to please." }
WordHunterWoW_QuestEN[61945] = { title = "The Professionals", description = "Smart move bringing in the specialists, {name}.\n\nOnce you get into this week's Ember Court, be sure to let the specialists know what you want them to do.\n\nBreakfist down in the dredger pools can smash or clean things to make the court more Messy or Clean for you.\n\nCrooked Crick in the refreshments area can adjust Decadence.\n\nLady Ilinca in the embassy area can adjust Formality.\n\nCosmin the Illusionist on stage can adjust Excitement.\n\nWing Commander Vulpek at the front gates can adjust Danger.", objectives = "Enter the Ember Court, then give orders to one of the specialist staff members.", completion = "Phew, those professionals know how to get a job done!\n\nI'll make sure they're at every Ember Court from now on, you just gotta swing by and give them orders before the gates open." }
WordHunterWoW_QuestEN[61946] = { title = "Natural Defenders", description = "", objectives = "Defeat Grixis Tinypop in a pet battle." }
WordHunterWoW_QuestEN[61947] = { title = "Lurking In The Shadows", description = "", objectives = "Defeat Grixis Tinypop in a pet battle." }
WordHunterWoW_QuestEN[61948] = { title = "Airborne Defense Force", description = "", objectives = "Defeat Grixis Tinypop in a pet battle." }
WordHunterWoW_QuestEN[61949] = { title = "Ardenweald's Tricksters", description = "", objectives = "Defeat Grixis Tinypop in a pet battle." }
WordHunterWoW_QuestEN[61950] = { title = "Hunting the Wilds", description = "The supply of attuned anima is running low again. I'm surprised that we've managed to stretch our resources so far without a resupply.\n\nYou've proven yourself proficient at tracking down what is needed, perhaps you could assist us once again?\n\nThe runestags that roam Ardenweald's forests are particularly suffused with the power of the wilds, anima retrieved from them will be optimal for our needs.\n\nGood hunting!", objectives = "Collect 10 Feral Anima from Runestags.", progress = "Worry not about the runestags, after some time they will return. This is just one part of the eternal cycle.", completion = "Good job! Your efforts will go a long way to keeping our production moving ahead.\n\nThank you!" }
WordHunterWoW_QuestEN[61957] = { title = "Champion: Ashraka", description = "", objectives = "My services are now yours Maw Walker." }
WordHunterWoW_QuestEN[61958] = { title = "Champion: Gorgelimb", description = "", objectives = "New master now!" }
WordHunterWoW_QuestEN[61959] = { title = "Champion: Talethi", description = "", objectives = "I shall pay my debt to my Maw Walker.\n\nDirect my power against your enemies." }
WordHunterWoW_QuestEN[61960] = { title = "Champion: Xertora", description = "", objectives = "Do you happen to have a spare leg lying around? Surely you don't need two. I'll put it to good use, kicking your enemies!\n\nNo? I can probably still help anyway." }
WordHunterWoW_QuestEN[61961] = { title = "Champion: Rattlebag", description = "", objectives = "I am prepared for combat!\n\nPut me in the front line, I will be your shield." }
WordHunterWoW_QuestEN[61962] = { title = "Champion: Velkein", description = "", objectives = "I shall wield my blade with purpose once more!\n\nDeath to your enemies!" }
WordHunterWoW_QuestEN[61963] = { title = "Called to the Hunt", description = "The Wild Hunt is made up of fae who have dedicated their lives to the protection of Ardenweald and its denizens. Each member has skill sharp as a blade and sense unlike no other.\n\nWe have spoken to a duo, an evoker and a huntress, who will permit us to capture their memories for training if we help them on a particular hunt.\n\nMeet Alderyn in Claw's Edge. He is one you seek.", objectives = "Find Alderyn in Claw's Edge in Ardenweald.", progress = "You are not of these lands. How may I aid you?", completion = "The envoy of the kyrian, armed with the perfect weapon to pierce our quarry's armor.\n\nAre you ready for a hunt?" }
WordHunterWoW_QuestEN[61964] = { title = "Aubrie Weekly Jailers Tower Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[61965] = { title = "Piercing the Shell", description = "Our quarry is one of the gorm, native creatures who were once helpful beasts of the realm, until the drought drove them mad.\n\nThis particular beast has not only grown to a frightening size, but also has a shell so strong that none of our weapons or arrows have managed to pierce it.\n\nThis spear you bring, infused with the anima of Bastion, could be the exact weapon we need to pierce the gorm's armor and put him down.\n\nMy sister went ahead to scout. Let's not linger.", objectives = "Find Myn'ir in the Gormhive, then kill the Fortified Desiccator.", completion = "The terror has been put down. Your aid, and your spear, were quite useful." }
WordHunterWoW_QuestEN[61967] = { title = "Remedial Lessons", description = "", objectives = "" }
WordHunterWoW_QuestEN[61968] = { title = "Just Wing It", description = "For untold ages, the humble Ardenmoth has supplied the scales for the creation of armor for the Wild Hunt. \n\nNow, with our attention divided between the threats to the realm and the anima drought, it has become increasingly difficult for our foragers to find the perfect scales that we require.\n\nOnly the scales of the highest quality are suitable. If you should obtain any in your travels and return with them, I shall ensure you are well rewarded.", objectives = "Collect 28 Perfect Ardenmoth Wing Scales from Ardenmoths.", progress = "Have you the scales?", completion = "Ah, remarkable quality! You've done well!" }
WordHunterWoW_QuestEN[61981] = { title = "Replenish the Reservoir", description = "Right, here's the gig: we need anima.\n\nNot just a bit or a pinch, but a lot. See, anythin' worth doin' can't be done without anima. Not in the Shadowlands. Not if we are gonna fix this mess Denathrius got us in.\n\nSo, we need your increasin'ly resourceful self to beg, borrow, steal, nick, burglarize, pulverize, pirate-ize, earn, swindle, or otherwise become the source of a great charity of any anima you can get.\n\nBring it to me, an' I'll stock our coffers, as it were, so you can put it to use.", objectives = "Collect anima sources for the Anima Reservoir at Sinfall in Revendreth.", progress = "How goes the anima hunt? You pinch us a pint or boost us keg?", completion = "Now that's a right grey professional job that is. This anima will get us makin' some fancy stuff in no time." }
WordHunterWoW_QuestEN[61982] = { title = "Replenish the Reservoir", description = "Hail, Maw Walker.\n\nAs our influence over Bastion grows, so too does our need for our most precious resource--anima.\n\nWe must replenish our reserves. Scour the realms for all that you can find and return here with the anima. \n\nWith our precious reserves replenished, we can direct the anima wherever it is needed most.\n\nGo in service, {class}.", objectives = "Collect anima sources for the Anima Reservoir at Elysian Hold in Bastion.", progress = "Every drop of anima is a gift in these times.", completion = "You have my thanks, Maw Walker. We will not let it go to waste." }
WordHunterWoW_QuestEN[61983] = { title = "Replenish the Reservoir", description = "We require your strength, Maw Walker.\n\nThe houses of our enemies grow stronger by the hour. In order to press the attack we must find new sources of anima to bolster our reserves.\n\nSearch the realms for this precious resource and bring it back here to the Sanctum. Let none deny you!\n\nWith your help the rival houses shall fall, one by one, and we will emerge victorious!", objectives = "Collect anima sources for the Anima Reservoir at Seat of the Primus in Maldraxxus.", progress = "The march to victory will require more anima.", completion = "Your contributions fuel our conquests on the battlefield. The final victory will be ours!" }
WordHunterWoW_QuestEN[61984] = { title = "Replenish the Reservoir", description = "Greetings, Maw Walker.\n\nThe Tirna Achiad, Heart of Ardenweald, flourishes in our care, yet more anima is needed for our Sanctum.\n\nThe cycle of rebirth, our purpose, must continue.\n\nTo help our Queen, we must acquire more. Will you help us replenish the reservoir?", objectives = "Collect anima sources for the Anima Reservoir at the Heart of the Forest in Ardenweald.", progress = "Have you come to dedicate anima to our sacred purpose?", completion = "The anima you have provided will nourish our precious groves. We thank you." }
WordHunterWoW_QuestEN[61985] = { title = "Wake The Sleepers", description = "The land speaks to me, {name}. Ardenweald is a realm of cycles, but it has never faced an anima drought such as this.\n\nWe will need the aid of all who reside here if we are to make it through this crisis.\n\nMany souls slumber within the forests and hills. If they can provide us some of their anima, we may be able to endure a little longer. Should you encounter any of the souls in your travels, please awaken them and send them to me.", objectives = "Awaken 8 Slumbering Souls.", completion = "This dew will help our craftmasters a great deal!\n\nThank you, little one." }
WordHunterWoW_QuestEN[61996] = { title = "Say The Magic Words", description = "Ever since I cast my first spell, I've not been able to get enough of magic!\n\nIt's not as hard as all those liches say it is. You focus your thoughts, say the words, and magic starts happening!\n\nThere are tomes documenting ancient spells stored in the Archivam of Revendreth. Help me gather them so I can learn some new spells!", objectives = "Help Sabrina learn 12 new spells in Revendreth.", completion = "You have helped strengthen our forces, Maw Walker." }
WordHunterWoW_QuestEN[61998] = { title = "Legacy of Stone", description = "", objectives = "We got room for another big statue on this here spot.\n\nYou get me some stone and I'll make whatever kind of statue you want, yeah?\n\nMaybe one of you, or someone else, yeah?", progress = "We got room for another big statue on this here spot.\n\nYou get me some stone and I'll make whatever kind of statue you want, yeah?\n\nMaybe one of you, or someone else, yeah?", completion = "Tell me what kind of sculpture you want me to make!" }
WordHunterWoW_QuestEN[62000] = { title = "Choosing Your Purpose", description = "Each covenant is vital to the Shadowlands. Though they have been isolated and divided as of late, the Purpose depends on the success of their efforts.\n\nAll of the covenants must bolster their strength to face the threat of the Banished One. But your contributions cannot be divided. They must be focused upon a single path. Other mortals may make a different choice.\n\nSpeak to your potential allies. Then make your choice at the map of the Shadowlands before me.", objectives = "Speak to the Covenants. Decide how your path is entwined with the Purpose.", progress = "Have you made your decision?", completion = "All is as expected. Trust always in the Arbiter's wisdom." }
WordHunterWoW_QuestEN[62041] = { title = "In A Bad Light", description = "I've heard about the chaos in Revendreth. Reports of exiles driven mad and burned in the Desiccation. \n\nThe very thought of all that suffering fills me with the urge to do something about it.\n\nIf you are headed there, please let me accompany you. I simply must help as many as I can!", objectives = "Use Roseboil's Regenerative Molt to cure 15 Light-Seared Exiles.", progress = "Did we cure them all?", completion = "Suffering is commonplace among those in Revendreth, but you and Roseboil were able to help a few of them nonetheless. \n\nWell done." }
WordHunterWoW_QuestEN[62043] = { title = "Prove Your Worth", description = "You must prove your worth to us again {name}.\n\nWe have not forgotten your betrayal.\n\nYet you say you seek penance. This task will start to demonstrate that you are serious about earning back our trust.", objectives = "Complete the task for the Kyrian.", completion = "So, you have done as we ask and are ready to rejoin our ranks?\n\nOnce you complete this task with me you will leave your current Covenant and rejoin the Kyrian." }
WordHunterWoW_QuestEN[62044] = { title = "Standing Toe To Toe", description = "<The gorger is clearly bigger, it gestures with its head towards one of the other gorgers as if urging you to attack it.>", objectives = "Defeat devourer gorgers.", progress = "Attack and defeat devourer gorgers in the Endmire.", completion = "<There is little expression you can see on the gorger's 'face' but it appears as if it is very full of itself as if it defeated them on its own. It does offer you a shiny thing it found.>" }
WordHunterWoW_QuestEN[62045] = { title = "Ready for More", description = "<Again the gorger is strutting ready for more fighting, staring down the the closest gorger.>", objectives = "Defeat devourer gorgers.", progress = "Attack and defeat devourer gorgers in the Endmire.", completion = "<Head high the gorger is really strutting his stuff and is clearly thinking you make a great team. He looks up at you ... and he spits up something that he thinks you might like.>" }
WordHunterWoW_QuestEN[62046] = { title = "A New Pack", description = "<The gorger is more than fully grown, rivaling most of the other devourers in the area. It clearly wants to stay with you, but it appears to be uneasy straying too far from the world eaters. Maybe if you take one down together it will not hold as much sway over the gorger.>", objectives = "Defeat an Unbidden Worldeater.", progress = "<The gorger gestures in the direction of a worldeater, seemingly feeling up to the challenge with you by its side.>", completion = "<The gorger is ecstatic that you took down a worldeater. It's excitement is palpable and it is on the brink of picking you up and carrying out off on a new adventure.>" }
WordHunterWoW_QuestEN[62051] = { title = "Gormling Toss: Spirit Glen", description = "", objectives = "" }
WordHunterWoW_QuestEN[62052] = { title = "Exiled by Paranoia", description = "The liches of the House of Rituals were an instrumental piece in the Maldraxxi attack on Bastion. They are not currenty our allies, and it would be difficult to convince one to let us capture their memory for our training purposes.\n\nWe have made contact with a necromancer who has a score to settle with one of the liches. Find her and she will aid you in capturing this memory.", objectives = "Find Karaxi the Defector in the Challenger's Promenade in Maldraxxus.", progress = "<Karaxi is sifting through a book very carefully.>", completion = "My plan is truly coming to fruition. An outsider, here to help me enact my revenge!" }
WordHunterWoW_QuestEN[62053] = { title = "Necromantic Power", description = "My old master, Thran'tiok, is the epitome of paranoia. She believes everybody will turn on her, and it led to my exilement from not only her service, but the House of Rituals as a whole.\n\nI had no intent to cross her... but that has changed.\n\nTake the crystal casing you have built and slay my old colleagues to infuse it with necromantic energy. It shall lead you to Thran'tiok's phylactery, which should be exactly what we both seek.", objectives = "Charge the Soulseeker Crystal by defeating foes in the House of Rituals, then use it to find Thran'tiok's phylactery.", progress = "Thran'tiok thinks I am a threat...\n\nI will show her what that word truly means.", completion = "We do not have much time. Thran'tiok will appear herself soon." }
WordHunterWoW_QuestEN[62054] = { title = "Castle Nathria: Getting a Head", description = "We need to show Denathrius that we mean business. His dredger... pet... should do the trick.\n\nBring me his head. Four times should do it. Dredgers are curious creatures.", objectives = "Collect 4 Sludgefist's Head from Sludgefist within Castle Nathria on Normal Difficulty.", progress = "I need the heads or we cannot make a profound statement.", completion = "With these I'm certain we'll catch the attention of Sire Denathrius." }
WordHunterWoW_QuestEN[62055] = { title = "Castle Nathria: Getting a Head", description = "We need to show Denathrius that we mean business. His dredger... pet... should do the trick.\n\nBring me his head. Four times should do it. Dredgers are curious creatures.", objectives = "Collect 4 Sludgefist's Head from Sludgefist within Castle Nathria on Heroic Difficulty.", progress = "I need the heads or we cannot make a profound statement.", completion = "With these I'm certain we'll catch the attention of Sire Denathrius." }
WordHunterWoW_QuestEN[62056] = { title = "Castle Nathria: Getting a Head", description = "We need to show Denathrius that we mean business. His dredger... pet... should do the trick.\n\nBring me his head. Four times should do it. Dredgers are curious creatures.", objectives = "Collect 4 Sludgefist's Head from Sludgefist within Castle Nathria on Mythic Difficulty.", progress = "I need the heads or we cannot make a profound statement.", completion = "With these I'm certain we'll catch the attention of Sire Denathrius." }
WordHunterWoW_QuestEN[62057] = { title = "Those Who Hunger", description = "I've heard reports that the number of gorm sightings have risen greatly the past few days.\n\nNormally they're simple decomposers, playing their part in the great cycle, but in great numbers the gorm can be aggressive. If left unchecked, their ravenous hunger will cause untold destruction.\n\nThe Wild Hunt has called for a gorm hunt. Meet your quota and you will be well-rewarded.", objectives = "Destroy 20 Gorm in Ardenweald.", completion = "Ah, good work. The gorm serve their purpose, but as in all things, balance must be maintained." }
WordHunterWoW_QuestEN[62058] = { title = "Centurions, Assemble!", description = "", objectives = "" }
WordHunterWoW_QuestEN[62059] = { title = "Prove Your Worth", description = "You must prove your worth to us again {name}.\n\nWe have not forgotten your betrayal.\n\nYet we know you seek penance. This task should prove your willingness to rejoin our ranks.", objectives = "Complete the task for the Necrolords.", completion = "So, you have done as we ask and are ready to rejoin our ranks?\n\nOnce you complete this task with me you will leave your current Covenant and rejoin the Necrolords." }
WordHunterWoW_QuestEN[62060] = { title = "Prove Your Worth", description = "You must prove your worth to us again {name}.\n\nWe have not forgotten your betrayal.\n\nYet we know you seek penance. This task should prove your willingness to rejoin our ranks.", objectives = "Complete the task for the Night Fae.", completion = "So, you have done as we ask and are ready to rejoin our ranks?" }
WordHunterWoW_QuestEN[62061] = { title = "Prove Your Worth", description = "You must prove your worth to us again {name}.\n\nWe have not forgotten your betrayal.\n\nYet we know you seek penance. This task should prove your willingness to rejoin our ranks.", objectives = "Complete the task for the Venthyr.", completion = "So, you have done as we ask and are ready to rejoin our ranks?" }
WordHunterWoW_QuestEN[62062] = { title = "Restock: Stolen Rugs", description = "", objectives = "Decorations not ready!\n\nLast Ember Court, those thieves steal more than memories. They steal rugs too!\n\nNew rugs be so heavy thieves can't carry! Bring me things to make heavy rugs.\n\nThen we can pick decorations for next court.", progress = "Decorations not ready!\n\nLast Ember Court, those thieves steal more than memories. They steal rugs too!\n\nNew rugs be so heavy thieves can't carry! Bring me things to make heavy rugs.\n\nThen we can pick decorations for next court.", completion = "Ha! New rugs be heavy and pretty... just like me.\n\nDecorations be ready for you now!" }
WordHunterWoW_QuestEN[62064] = { title = "Restock: Broken Mirrors", description = "", objectives = "Decorations not ready!\n\nLast Ember Court, those prisoners break all the mirrors when they escape!\n\nLaurent help me fix, but need pieces.\n\nThen we can pick decorations for next court.", progress = "Decorations not ready!\n\nLast Ember Court, those prisoners break all the mirrors when they escape!\n\nLaurent help me fix, but need pieces.\n\nThen we can pick decorations for next court.", completion = "With mirrors fixed, I can see my pretty face again.\n\nDecorations be ready for you now!" }
WordHunterWoW_QuestEN[62065] = { title = "Restock: My Favorite Table", description = "", objectives = "Decorations not ready!\n\nLast Ember Court, one of them big bad dredgers sit on my favorite table, break in half!\n\nNeed wood to fix table.\n\nThen we can pick decorations for next court.", progress = "Decorations not ready!\n\nLast Ember Court, one of them big bad dredgers sit on my favorite table, break in half!\n\nNeed wood to fix table.\n\nThen we can pick decorations for next court.", completion = "I make sure no big bad dredgers sit on my table again.\n\nDecorations be ready for you now!" }
WordHunterWoW_QuestEN[62066] = { title = "Restock: Dredger Pool", description = "", objectives = "Decorations not ready!\n\nLast Ember Court, that big slimeball leaked slimeball slime into our muckpool. Every new dredger all slimy!\n\nNeed way to get rid of all bad stuff... You know thing does that?\n\nThen we can pick decorations for next court.", progress = "Decorations not ready!\n\nLast Ember Court, that big slimeball leaked slimeball slime into our muckpool. Every new dredger all slimy!\n\nNeed way to get rid of all bad stuff... You know thing does that?\n\nThen we can pick decorations for next court.", completion = "Okay... I pour into muckpool and see if helps.\n\nDecorations be ready for you now!" }
WordHunterWoW_QuestEN[62067] = { title = "Restock: Statues", description = "", objectives = "Decorations not ready!\n\nLast Ember Court, dredgers see big new statue made. All want statues now!\n\nBring me stone and I carve tiny statues to hold. Make all dredgers happy.\n\nThen we can pick decorations for next court.", progress = "Decorations not ready!\n\nLast Ember Court, dredgers see big new statue made. All want statues now!\n\nBring me stone and I carve tiny statues to hold. Make all dredgers happy.\n\nThen we can pick decorations for next court.", completion = "Maybe I carve for prince too. He like statues, yeah?\n\nDecorations be ready for you now!" }
WordHunterWoW_QuestEN[62068] = { title = "Gormling Piper: Crumbled Ridge", description = "", objectives = "" }
WordHunterWoW_QuestEN[62069] = { title = "Restock: Sinstones", description = "", objectives = "We got a problem, <name>.\n\nLast Ember Court, the Accuser's rituals were a little TOO convincing. A bunch of my dredgers want their own sinstones now, so they can list things they think they've done wrong.\n\nI'm going to need some resources to soothe their guilty consciences.\n\nThen we can pick our entertainment for the next Ember Court.", progress = "We got a problem, <name>.\n\nLast Ember Court, the Accuser's rituals were a little TOO convincing. A bunch of my dredgers want their own sinstones now, so they can list things they think they've done wrong.\n\nI'm going to need some resources to soothe their guilty consciences.\n\nThen we can pick our entertainment for the next Ember Court.", completion = "I can't believe we're doing this... But I am curious to see what the crew writes on these.\n\nWe can book the next Entertainment whenever you're ready." }
WordHunterWoW_QuestEN[62070] = { title = "Restock: Fragrant Flowers", description = "", objectives = "We got a problem, <name>.\n\nLast Ember Court, some of the animals had... issues. I can't get the stains out and everything reeks!\n\nI'm going to need some very fragrant flowers to cover up this smell.\n\nThen we can pick our entertainment for the next Ember Court.", progress = "We got a problem, <name>.\n\nLast Ember Court, some of the animals had... issues. I can't get the stains out and everything reeks!\n\nI'm going to need some very fragrant flowers to cover up this smell.\n\nThen we can pick our entertainment for the next Ember Court.", completion = "These smell great! Or at least better than the current smell...\n\nWe can book the next Entertainment whenever you're ready." }
WordHunterWoW_QuestEN[62071] = { title = "RRP Test Quest", description = "RRP Test Quest", objectives = "" }
WordHunterWoW_QuestEN[62072] = { title = "Familiar Faces", description = "<You arrive alone at the precipice of a strange city, knowing the leaders of Azeroth remain trapped in the Maw.\n\nWherever you are, it is clearly very, very far from home.\n\nIt appears your arrival has been noticed.>", objectives = "" }
WordHunterWoW_QuestEN[62073] = { title = "Restock: Band Shirts", description = "", objectives = "We got an opportunity, <name>.\n\nThe Lost Chalice Band is the hottest entertainment in Revendreth after that killer performance at the last Ember Court. It's all anyone's talking about.\n\nWe should make some band shirts, give 'em out for free to keep the hype rolling.\n\nBring me the materials and I'll take care of the rest.\n\nThen we can pick our entertainment for the next Ember Court.", progress = "We got an opportunity, <name>.\n\nThe Lost Chalice Band is the hottest entertainment in Revendreth after that killer performance at the last Ember Court. It's all anyone's talking about.\n\nWe should make some band shirts, give 'em out for free to keep the hype rolling.\n\nBring me the materials and I'll take care of the rest.\n\nThen we can pick our entertainment for the next Ember Court.", completion = "Soon every socialite in Revendreth will wearing one of these, promoting our court.\n\nWe can book the next Entertainment whenever you're ready." }
WordHunterWoW_QuestEN[62074] = { title = "Professions - Reuse", description = "You've found what appears to be a memory of sorts. Perhaps it's another of the Runecarver's stolen memories.", objectives = "Bring the memory back to the Runecarver." }
WordHunterWoW_QuestEN[62075] = { title = "Restock: Soul Cages", description = "", objectives = "We got a problem, <name>.\n\nLast Ember Court, we were able to save quite of a few of those abused souls the Master's minions attacked us with. \n\nThat's great, but we need more chains and cages if we're going to keep that many souls here until the Accuser can take them.\n\nThen we can pick our entertainment for the next Ember Court.", progress = "We got a problem, <name>.\n\nLast Ember Court, we were able to save quite of a few of those abused souls the Master's minions attacked us with. \n\nThat's great, but we need more chains and cages if we're going to keep that many souls here until the Accuser can take them.\n\nThen we can pick our entertainment for the next Ember Court.", completion = "I'll get the ritualists to help us build the cages, so they'll be done right.\n\nWe can book the next Entertainment whenever you're ready." }
WordHunterWoW_QuestEN[62076] = { title = "Restock: Free Press", description = "", objectives = "We got a problem, <name>.\n\nLast Ember Court, that provocateur's gossip spread further than we thought. I've gotten all sorts of uncomfortable questions from socialites and nobles unsure of what to believe.\n\nWe've got to write some pamphlets to set the record straight and dispel that scoundrel's lies!\n\nThen we can pick our entertainment for the next Ember Court.", progress = "We got a problem, <name>.\n\nLast Ember Court, that provocateur's gossip spread further than we thought. I've gotten all sorts of uncomfortable questions from socialites and nobles unsure of what to believe.\n\nWe've got to write some pamphlets to set the record straight and dispel that scoundrel's lies!\n\nThen we can pick our entertainment for the next Ember Court.", completion = "Writing letters: one of the oldest forms of entertainment.\n\nWe can book the next Entertainment whenever you're ready." }
WordHunterWoW_QuestEN[62077] = { title = "To the Chase", description = "You have been to the Maw and seen the Jailer, yes? His forces threaten the entire Shadowlands.\n\nThe covenants of Shadowlands are trying to fight back against the Jailer. They could use your aid.\n\nTal-Inara, the voice of the Arbiter, wishes to speak with you. She will help you with your Purpose.\n\nMake haste.", objectives = "" }
WordHunterWoW_QuestEN[62078] = { title = "Restock: Fashion Accessories", description = "", objectives = "We got a problem, <name>.\n\nLast Ember Court, the Countess's clothier showed everyone the future of fashion and we're all way behind. Medallions are all the rage, thanks to the Prince's growing collection.\n\nI can't get a medallion, but I at least need a necklace so I don't get laughed out of courts.\n\nThen we can pick our entertainment for the next Ember Court.", progress = "We got a problem, <name>.\n\nLast Ember Court, the Countess's clothier showed everyone the future of fashion and we're all way behind. Medallions are all the rage, thanks to the Prince's growing collection.\n\nI can't get a medallion, but I at least need a necklace so I don't get laughed out of courts.\n\nThen we can pick our entertainment for the next Ember Court.", completion = "I can't believe I'm going to wear this gaudy necklace, but if this is what it takes to make sure we always have access to the best entertainment...\n\n<Hips sighs.>\n\nWe can book the next Entertainment whenever you're ready." }
WordHunterWoW_QuestEN[62080] = { title = "Restock: Herbal Tea", description = "", objectives = "I suffer yet another crisis in the kitchen, Maw Walker!\n\nLast Ember Court, our guests drank more tea than Theotar himself! Our entire supply is depleted.\n\nI simply must acquire new tea ingredients, and I only accept the highest quality!\n\nAfter that, I shall happily discuss refreshment options for our next court.", progress = "I suffer yet another crisis in the kitchen, Maw Walker!\n\nLast Ember Court, our guests drank more tea than Theotar himself! Our entire supply is depleted.\n\nI simply must acquire new tea ingredients, and I only accept the highest quality!\n\nAfter that, I shall happily discuss refreshment options for our next court.", completion = "Ah yes, these shall make a glorious tea once I have dehydrated them.\n\nNow we may discuss refreshments for our next Ember Court." }
WordHunterWoW_QuestEN[62081] = { title = "Return Those Animacones!", description = "Reports say that once again the spriggan are proving to be a nuisance, {name}.\n\nWord is that a bunch of them broke into the stores at the Heart of the Forest and made off with a huge store of animacones.\n\nNeedless to say, we need those animacones back.\n\nThe report says the spriggan group split up as they were making their escape, so any one you see is as likely to be carrying the animacones as the next. \n\nGood luck.", objectives = "Collect 44 Looted Animacones from spriggan within Ardenweald.", progress = "Were you able to find the animacones?", completion = "You were able to retrieve all of them? Outstanding!" }
WordHunterWoW_QuestEN[62082] = { title = "Restock: Personal Stash", description = "", objectives = "I suffer yet another crisis in the kitchen, Maw Walker!\n\nLast Ember Court, while your guests were so flippantly flinging food around court, several stray pies flew directly into my personal food supplies. Everything was ruined!\n\nYou know I do not like to make a fuss, but I simply must insist that you replace the delicacies ruined by that unwelcome food fight.\n\nAfter that, I shall happily discuss refreshment options for our next court.", progress = "I suffer yet another crisis in the kitchen, Maw Walker!\n\nLast Ember Court, while your guests were so flippantly flinging food around court, several stray pies flew directly into my personal food supplies. Everything was ruined!\n\nYou know I do not like to make a fuss, but I simply must insist that you replace the delicacies ruined by that unwelcome food fight.\n\nAfter that, I shall happily discuss refreshment options for our next court.", completion = "Thank you. All is forgiven.\n\nNow we may discuss refreshments for our next Ember Court." }
WordHunterWoW_QuestEN[62083] = { title = "Restock: Medical Supplies", description = "", objectives = "I suffer yet another crisis in the kitchen, Maw Walker!\n\nLast Ember Court, those wild mushrooms you brought poisoned me and half of the socialites!\n\nThankfully, it does not appear to be a lethal poison, but it has been most uncomfortable for all involved.\n\nWe are in desperate need of anti-venom.\n\nAfter that, I shall happily discuss refreshment options for our next court.", progress = "I suffer yet another crisis in the kitchen, Maw Walker!\n\nLast Ember Court, those wild mushrooms you brought poisoned me and half of the socialites!\n\nThankfully, it does not appear to be a lethal poison, but it has been most uncomfortable for all involved.\n\nWe are in desperate need of anti-venom.\n\nAfter that, I shall happily discuss refreshment options for our next court.", completion = "<Picky Stefan pinches his nose and sips from the potion vial.>\n\nI have never been more eager to consume something that tastes so foul.\n\nNow we may discuss refreshments for our next Ember Court." }
WordHunterWoW_QuestEN[62084] = { title = "Restock: Fine Cutlery", description = "", objectives = "I suffer yet another crisis in the kitchen, Maw Walker!\n\nLast Ember Court, the venthyr invaders did not just assault our guests--they stole our cutlery!\n\nMy old friend Forgy can craft replacement cutlery for us, but we will need to provide the supplies.\n\nAfter that, I shall happily discuss refreshment options for our next court.", progress = "I suffer yet another crisis in the kitchen, Maw Walker!\n\nLast Ember Court, the venthyr invaders did not just assault our guests--they stole our cutlery!\n\nMy old friend Forgy can craft replacement cutlery for us, but we will need to provide the supplies.\n\nAfter that, I shall happily discuss refreshment options for our next court.", completion = "The old cutlery was due to be replaced anyway.\n\nNow we may discuss refreshments for our next Ember Court." }
WordHunterWoW_QuestEN[62085] = { title = "...Why Me?", description = "<The dense, chunky liquid inside the vessel emits a horrendous odor.\n\nThe initials O.K. are etched into the side. It seems someone stole Overseer Kalvaros' canteen.>", objectives = "Deliver the Reclaimed Vessel to Overseer Kalvaros at the Challenger's Promenade.\n\nProvided item:", completion = "I've been wondering where my canteen went. Where did you find this, <name>? Did you take a drink before returning here?\n\nNo matter, I suppose." }
WordHunterWoW_QuestEN[62086] = { title = "Professions - Reuse", description = "You've found what appears to be a memory of sorts. Perhaps it's another of the Runecarver's stolen memories.", objectives = "Bring the memory back to the Runecarver." }
WordHunterWoW_QuestEN[62087] = { title = "Restock: Imported Dinnerware", description = "", objectives = "I suffer yet another crisis in the kitchen, Maw Walker!\n\nLast Ember Court, the stone fiends dropped more than Theotar's tea set. They broke the dinnerware I had imported directly from Ardenweald, in order to help our Night Fae guests feel at home!\n\nI believe I can repair them, but I will need resources.\n\nAfter that, I shall happily discuss refreshment options for our next court.", progress = "I suffer yet another crisis in the kitchen, Maw Walker!\n\nLast Ember Court, the stone fiends dropped more than Theotar's tea set. They broke the dinnerware I had imported directly from Ardenweald, in order to help our Night Fae guests feel at home!\n\nI believe I can repair them, but I will need resources.\n\nAfter that, I shall happily discuss refreshment options for our next court.", completion = "I am certain that our Night Fae friends will appreciate the effort we have gone through to accommodate them.\n\nNow we may discuss refreshments for our next Ember Court." }
WordHunterWoW_QuestEN[62088] = { title = "Professions - Reuse", description = "You've found what appears to be a memory of sorts. Perhaps it's another of the Runecarver's stolen memories.", objectives = "Bring the memory back to the Runecarver." }
