WordHunterWoW_QuestEN[62093] = { title = "Professions - Reuse", description = "You've found what appears to be a memory of sorts. Perhaps it's another of the Runecarver's stolen memories.", objectives = "Bring the memory back to the Runecarver." }
WordHunterWoW_QuestEN[62094] = { title = "Restock: Exploratory Meals", description = "", objectives = "I suffer yet another crisis in the kitchen, Maw Walker!\n\nYou may recall that an excess of gnats swarmed our last Ember Court. Although initially repulsed, I have begun to ponder if there might be some culinary value to these creatures.\n\nI would like to attempt a few meals with them. I shall require a few things to steel myself for the culinary adventure.\n\nAfter that, I shall happily discuss refreshment options for our next court.", progress = "I suffer yet another crisis in the kitchen, Maw Walker!\n\nYou may recall that an excess of gnats swarmed our last Ember Court. Although initially repulsed, I have begun to ponder if there might be some culinary value to these creatures.\n\nI would like to attempt a few meals with them. I shall require a few things to steel myself for the culinary adventure.\n\nAfter that, I shall happily discuss refreshment options for our next court.", completion = "Wish me luck... I fear that I shall need it.\n\nNow we may discuss refreshments for our next Ember Court." }
WordHunterWoW_QuestEN[62095] = { title = "Restock: Medic's Tent", description = "", objectives = "I have an urgent matter to discuss.\n\nWhile the volunteer portion of our security showed tremendous bravery at the last Ember Court, it was clear that they were unprepared for the rigors of battle. They suffered tremendous injuries.\n\nWe need to resupply our medical team to be ready for the next court.\n\nAfter that is resolved, we can discuss security options for future Ember Courts.", progress = "I have an urgent matter to discuss.\n\nWhile the volunteer portion of our security showed tremendous bravery at the last Ember Court, it was clear that they were unprepared for the rigors of battle. They suffered tremendous injuries.\n\nWe need to resupply our medical team to be ready for the next court.\n\nAfter that is resolved, we can discuss security options for future Ember Courts.", completion = "Thank you. Caring for the wounded is an honorable endeavor.\n\nThe full breadth of our Security options are available to us now." }
