WordHunterWoW_QuestEN[62104] = { title = "Restock: Stoneborn Reserves", description = "", objectives = "I have an urgent matter to discuss.\n\nAt the last Ember Court, many of our stoneborn suffered fractures and cracked limbs while defending our guests. We will need to repair them.\n\nBring me the stone, and I will coordinate the repairs with our dredgers.\n\nAfter that is resolved, we can discuss security options for future Ember Courts.", progress = "I have an urgent matter to discuss.\n\nAt the last Ember Court, many of our stoneborn suffered fractures and cracked limbs while defending our guests. We will need to repair them.\n\nBring me the stone, and I will coordinate the repairs with our dredgers.\n\nAfter that is resolved, we can discuss security options for future Ember Courts.", completion = "This should be enough to rebuild the fallen stoneborn.\n\nThe full breadth of our Security options are available to us now." }
WordHunterWoW_QuestEN[62105] = { title = "Restock: Unconventional Weapons", description = "", objectives = "I have an urgent matter to discuss.\n\nFighting alongside the Maldraxxi forces at the last Ember Court inspired me to strategize outside of the typical boundaries of venthyr warfare.\n\nI am certain you mortals have developed creative weapons. Bring me some, so that I may learn them.\n\nAfter that is resolved, we can discuss security options for future Ember Courts.", progress = "I have an urgent matter to discuss.\n\nFighting alongside the Maldraxxi forces at the last Ember Court inspired me to strategize outside of the typical boundaries of venthyr warfare.\n\nI am certain you mortals have developed creative weapons. Bring me some, so that I may learn them.\n\nAfter that is resolved, we can discuss security options for future Ember Courts.", completion = "Interesting. I did not expect them to be so... mechanical.\n\nThe full breadth of our Security options are available to us now." }
WordHunterWoW_QuestEN[62106] = { title = "Restock: Enchantments", description = "", objectives = "I have an urgent matter to discuss.\n\nThe Stone Legion's surprise attack on our last Ember Court revealed that I have been far too lax in pursuing enchantments for our troops' equipment. We must use every advantage at our disposal.\n\nBring me any enchantment you can spare.\n\nAfter that is resolved, we can discuss security options for future Ember Courts.", progress = "I have an urgent matter to discuss.\n\nThe Stone Legion's surprise attack on our last Ember Court revealed that I have been far too lax in pursuing enchantments for our troops' equipment. We must use every advantage at our disposal.\n\nBring me any enchantment you can spare.\n\nAfter that is resolved, we can discuss security options for future Ember Courts.", completion = "The next time the Stone Legion invades, we'll be ready for them.\n\nThe full breadth of our Security options are available to us now." }
WordHunterWoW_QuestEN[62108] = { title = "Restock: Strategic Codices", description = "", objectives = "I have an urgent matter to discuss.\n\nAt the last Ember Court, the devourer's ambush tactics caught our guards by surprise. Their portals opened all around us and we were too slow to respond.\n\nWe should stock up on supplies that will allow us to adapt to changing circumstances.\n\nAfter that is resolved, we can discuss security options for future Ember Courts.", progress = "I have an urgent matter to discuss.\n\nAt the last Ember Court, the devourer's ambush tactics caught our guards by surprise. Their portals opened all around us and we were too slow to respond.\n\nWe should stock up on supplies that will allow us to adapt to changing circumstances.\n\nAfter that is resolved, we can discuss security options for future Ember Courts.", completion = "Even those made of stone can change with time.\n\nThe full breadth of our Security options are available to us now." }
WordHunterWoW_QuestEN[62109] = { title = "Restock: Surveillance Equipment", description = "", objectives = "I have an urgent matter to discuss.\n\nAs you are aware, a murder occurred at the last Ember Court. That is an unacceptable failing on my part and I apologize.\n\nI would like to acquire additional surveillance equipment to ensure we are prepared if it happens again.\n\nAfter that is resolved, we can discuss security options for future Ember Courts.", progress = "I have an urgent matter to discuss.\n\nAs you are aware, a murder occurred at the last Ember Court. That is an unacceptable failing on my part and I apologize.\n\nI would like to acquire additional surveillance equipment to ensure we are prepared if it happens again.\n\nAfter that is resolved, we can discuss security options for future Ember Courts.", completion = "I tolerate many questionable activities in the court, but murder will not be one of them.\n\nThe full breadth of our Security options are available to us now." }
