WordHunterWoW_QuestEN[62155] = { title = "Runestone Roundup", description = "Stone is a rare material in Ardenweald. Yet, I've heard tales that those who were masked by the Drust have small stones upon them.\n\nI'd like you to retrieve some of these stones for the Wild Hunt, so that we may better understand their link to our enemy.\nFace the masked and collect the stones from their deceased forms and I'll compensate you for your efforts.\n\nIt's a gruesome task, but one that must be done.", objectives = "Collect 18 Runestone Spikes from drust possessed fae within Ardenweald.", progress = "How goes your investigation?", completion = "You were able to retrieve all of them? Outstanding!" }
WordHunterWoW_QuestEN[62157] = { title = "Scouting from a Safe Distance", description = "The resurgence of the Scourge is troubling enough, but there are also reports that the Cult of the Damned has risen anew as well.\n\nIf true, then that bodes ill for us all. We cannot allow the cultists' machinations to continue unchecked.\n\nI suggest we engage in some reconnaissance.", objectives = "Survey the Cult of the Damned's presence at Aldur'thar and Mord'rethar.", progress = "Notice anything unusual?", completion = "They must be planning something. Though what, I cannot say.\n\nI will instruct our scouts to observe and report." }
WordHunterWoW_QuestEN[62159] = { title = "Aiding the Shadowlands", description = "There is much to do within the Shadowlands. Many areas are suffering from the anima drought.\n\nThe choice of who to help first is yours. Where will you go?", objectives = "Choose where to go in the Shadowlands.", completion = "This is your first step towards thwarting the Jailer." }
WordHunterWoW_QuestEN[62160] = { title = "A Bundle of Lilies", description = "This grove needs something special, something to make it really stand out.\n\nI have a plan, but first I need flowers.\n\nNot just any flowers, but Night Lillies. They have a sweet scent that evokes starlit nights spent standing on a hilltop overlooking the majesty of the land.\n\nAs you go exploring Ardenweald, look to the waterways for Night Lillies growing in the waterways and collect them.\nI will pay you for your efforts, of course.", objectives = "Collect 10 Night Lillies.", progress = "Were you able to find any of the lillies?", completion = "Ah, their scent is lovely!\n\nHaving a few of these placed around the grove will greatly help with morale." }
WordHunterWoW_QuestEN[62161] = { title = "Blood from a Bone", description = "I want nothing more than to make for Revendreth immediately... but it seems they have their own challenges to face.\n\nAll know of the mark we left on Bastion. The venthyr are sure to be wary of allowing us into their realm.\n\nOnce again, we must turn to you. Your renown across the Shadowlands has earned you the trust of many. Now, we need the trust of Revendreth.", objectives = "Increase your Renown.", completion = "You're just in time. I've received a missive." }
WordHunterWoW_QuestEN[62162] = { title = "A Message from the Justicar", description = "Justicar Trueheart has sent a personal request for your immediate assistance, {name}.\n\nThe frozen winds of Icecrown await your return.", objectives = "Report to Justicar Mariel Trueheart at the Argent Tournament Grounds in Icecrown.", completion = "I am glad for your return, <name>." }
WordHunterWoW_QuestEN[62163] = { title = "A Message from the Justicar", description = "Justicar Trueheart has sent a personal request for your immediate assistance, {name}.\n\nThe frozen winds of Icecrown await your return.", objectives = "Report to Justicar Mariel Trueheart at the Argent Tournament Grounds in Icecrown.", completion = "I am glad for your return, <name>." }
WordHunterWoW_QuestEN[62165] = { title = "Tal-Inara's Call", description = "Your presence is needed within the Enclave.\n\nIt is time for you to choose a covenant to ally yourself with.", objectives = "Meet Tal-Inara within the Enclave in Oribos.Your presence is needed within the Enclave.\n\nIt is time for you to choose a covenant to ally yourself with.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[62166] = { title = "Tal-Inara's Call", description = "Your presence is needed within the Enclave.\n\nIt is time for you to choose a covenant to ally yourself with.", objectives = "Meet Tal-Inara within the Enclave in Oribos.Your presence is needed within the Enclave.\n\nIt is time for you to choose a covenant to ally yourself with.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[62168] = { title = "Bonescript Dispatches", description = "", objectives = "" }
WordHunterWoW_QuestEN[62169] = { title = "Eyes to the Sky", description = "The House of Eyes still reels from Akarek's demise. They search for direction. For purpose.\n\nPerhaps you can help them find it. Continue to gain the trust of the Eyes. Their skills will be invaluable to our cause.", objectives = "Increase your Renown.", completion = "You've done well, Maw Walker. The Eyes place their trust in you." }
WordHunterWoW_QuestEN[62170] = { title = "You'll Never Walk Alone", description = "<You have stumbled upon some messy notes. Some of the lines seem incomprehensible while others seem melodic.>\n\nLike wind and rain, discord storms my mind, tossing and blowing.\n...\nI must find the golden skies.\n...\nRemember, walk on, heart full of hope, and you'll never walk alone.\n\n<It seems as though an aspirant cannot find their way home. You should inform someone at Hero's Rest.>", objectives = "Turn these notes in to Inkiep in Hero's Rest.", completion = "Ah, these wise words are certainly Eurgon's. I'm happy to report he made it home." }
WordHunterWoW_QuestEN[62171] = { title = "Tea Time", description = "", objectives = "" }
WordHunterWoW_QuestEN[62172] = { title = "Shortsleeved Doublet", description = "Is that a slightly worn doublet for me!", objectives = "Is that a slightly worn doublet for me!", progress = "Is that a slightly worn doublet for me!", completion = "Thank you! I will put this away until the time is right to wear it." }
WordHunterWoW_QuestEN[62173] = { title = "Long Sleeved Doublet", description = "<Your dredger reaches out enthusiastically for the long sleeved doublet.>", objectives = "<Your dredger reaches out enthusiastically for the long sleeved doublet.>", progress = "<Your dredger reaches out enthusiastically for the long sleeved doublet.>", completion = "Oooh, it has sleeves that go past my elbows, thank you! I can't wait until we find the right time to wear it." }
WordHunterWoW_QuestEN[62174] = { title = "A Proper Cover", description = "<Your dredger butler eyes you as if not sure if you are giving him the coif, or just asking him to hold it for you.>", objectives = "<Your dredger butler eyes you as if not sure if you are giving him the coif, or just asking him to hold it for you.>", progress = "<Your dredger butler eyes you as if not sure if you are giving him the coif, or just asking him to hold it for you.>", completion = "Is that a cap for me? It is so floppy, I love it! And it will go around my ears!" }
WordHunterWoW_QuestEN[62175] = { title = "Looking Fabulous", description = "Who is this? Oh, look at those flowing locks...", objectives = "Who is this? Oh, look at those flowing locks...", progress = "Who is this? Oh, look at those flowing locks...", completion = "<Your butler shakes his head back and forth imagining the flowing locks in the portrait.>\n\nOooh, thanks, I am sure we could find a good time to cut my hair like this!" }
WordHunterWoW_QuestEN[62176] = { title = "The Spikey Look", description = "That creature has a very distinct look...", objectives = "That creature has a very distinct look...", progress = "That creature has a very distinct look...", completion = "I bet if I curled into a ball using it the spikes would be pretty scary, not that I would think of doing anything like that at a party, unless we could use that... I will just save this poster for when the time is right for this cut." }
WordHunterWoW_QuestEN[62177] = { title = "A Memorable Look", description = "Oh, I have seen this dredger before!", objectives = "Oh, I have seen this dredger before!", progress = "Oh, I have seen this dredger before!", completion = "Ooh, this look feels fitting for a role like mine, I am sure many other dredgers have assisted while sporting this sparse, scraggly look. I can't wait to try it out!" }
WordHunterWoW_QuestEN[62178] = { title = "Black Muck Dye", description = "Another muck dye!", objectives = "Another muck dye!", progress = "Another muck dye!", completion = "Ah, black muck, it stains the fingers, but is very distinguished. I will save this for the next time we need to dye my doublet. I want to remind you that we will need one for each dying, but I can keep this one ready." }
WordHunterWoW_QuestEN[62179] = { title = "Blue Muck Dye", description = "Isn't muck so versatile!", objectives = "Isn't muck so versatile!", progress = "Isn't muck so versatile!", completion = "Do you think the blue muck looks like the sky? Dirk thought it did, but I don't think so. I will save this for the next time we need to dye my doublet. I want to remind you that we will need one for each dying, but I can keep this one ready." }
WordHunterWoW_QuestEN[62180] = { title = "Green Muck Dye", description = "There are so many muck colors, how do you choose just one?", objectives = "There are so many muck colors, how do you choose just one?", progress = "There are so many muck colors, how do you choose just one?", completion = "I have only visited the Banewood Muck Pool once, but I found it was a bit crowded myself, I definitely prefer working solo. I will save this for the next time we need to dye my doublet. I want to remind you that we will need one for each dying, but I can keep this one ready." }
WordHunterWoW_QuestEN[62181] = { title = "Bubbling Red Muck Dye", description = "Is that one still bubbling?", objectives = "Is that one still bubbling?", progress = "Is that one still bubbling?", completion = "Ooh, its still warm. I could live out in the Ember Ward. I will save this for the next time we need to dye my doublet. I want to remind you that we will need one for each dying, but I can keep this one ready." }
WordHunterWoW_QuestEN[62182] = { title = "A Letter From Nadja", description = "The letter is addressed to Nadja's contact Dimwiddle in Darkhaven. It is clearly sealed with Nadja's mark. It is certainly of great import, you should make sure the letter is delivered.", objectives = "Return the letter to Darkhaven.\n\nProvided item:", completion = "Uh, what can Dimwiddle do for you? Oh, a letter... <Dimwiddle sees Nadja's mark and his eyes go wide> yes, thank you I have been awaiting that letter. It's from my aunt <Dimwiddle winks at you> she has been ill. I will make sure to tell everyone you helped deliver important letters!" }
WordHunterWoW_QuestEN[62183] = { title = "A Leaking Box Marked Perishable", description = "A very exact entity wanted this package to reach Ta'tru at the Night Market. It looks like Broker script. The package is clearly leaking, and it is marked perishable. Perhaps delivering it quickly would be best.", objectives = "Deliver the package to the Night Market.\n\nProvided item:", completion = "Ooh, is that my package of flesh-eating ooze?! I hope you did not get any on your hands. Wearing gloves while handling this particular ooze should mean you have only a 25% chance of suffering an adverse effect. The gloves may be burned, but I will leave that to your discretion. I will inform the locals of your assistance in delivery, even if it was delayed." }
WordHunterWoW_QuestEN[62184] = { title = "A Crate of Sinvyr Ore", description = "The crate is fairly big and looks heavy, but it also looks like something someone would be willing to compensate for. Take the crate to Gibbo at the Old Gate. He should be expecting the recurring shipment.", objectives = "Deliver the crate to the Old Gate.\n\nProvided item:", completion = "Finally! What have you been doing with that shipment? You are a week late and now I am behind. <He sees you starting to talk and carries on.> No, I don't want to hear it. I won't be giving you a good review for this delivery, but here is the arranged cut of the shipment." }
WordHunterWoW_QuestEN[62185] = { title = "Fighting for Attention", description = "Maintaining a watchful eye on the Cult of the Damned has proven challenging... and perilous.\n\nSeveral of our hippogryph riders recently ran afoul of the cult's winged terrors. Though a few were able to escape, the others were captured and brought to Aldur'thar.\n\nDo what you can to free them from their captors. We cannot afford to lose any more of our forces.", objectives = "Free 5 Argent Hippogryph Riders from Aldur'thar.", completion = "You have my gratitude.\n\nI assure you this will not be forgotten." }
WordHunterWoW_QuestEN[62186] = { title = "Swollen Anima Seed", description = "The masked sylvar set aside a single seed laden with anima; for what purpose, you can only imagine. Droman Tashmur would appreciate the return of such a precious resource.", objectives = "Return the Swollen Anima Seed to Droman Tashmur in Tirna Vaal.\n\nProvided item:", completion = "What have you brought me? Why would the masked ones be collecting anima so? A concern for the future. Thank you for bringing this to me. It will nourish many wildseeds." }
WordHunterWoW_QuestEN[62187] = { title = "Satchel of Culexwood", description = "This lost satchel is filled with wood given by the nearby Culex trees. Fluttercatch would surely appreciate its return.", objectives = "Return the Satchel of Culexwood to Fluttercatch in the Banks of Life.\n\nProvided item:", completion = "A whole sackful?! Wonderful! I'll be sure to put this to good use." }
WordHunterWoW_QuestEN[62188] = { title = "Catch A Star", description = "I require your aid on a... delicate matter, {name}.\n\nStarfly Wings form a vital ingredient for some of our creations and our supply is exhausted.\nThey are tiny things, very fragile, and I am ill able to handle them delicately.\n\nCould you obtain the Starflies for me? They must be caught alive in order for their wings to not spoil and we desperately need them. \n\nI'll ensure that you are compensated for your time, of course.", objectives = "Collect 13 Glittering Starflies.", completion = "Outstanding! I could see the shine coming from your pack before you even arrived.\n\nThank you!" }
WordHunterWoW_QuestEN[62189] = { title = "Parasol Components", description = "Sheets of fine cloth, wooden parasol ribs, wooden dowels and metal braces, everything you would need to put together new parasols. These are worth a lot of gold in the Ember Ward. Mats would certainly reward you handsomely if you brought him this cache.", objectives = "Return the components to Sanctuary of the Mad.\n\nProvided item:", completion = "Oh, wow, this is a real find you have. Here, a heap of Infused Rubies for the bundle, the best you will see here in the ward. And if you see one of my goods you might like, let me know." }
WordHunterWoW_QuestEN[62190] = { title = "It's a Dirty Job", description = "We gotta fix up this muck pool before we go makin' that dredger butler of yours.\n\nLooks like the anima shortage caused all sorts of problems for this pool.\n\nThem muck pools gotta have plenty of filth and fiber in 'em to grow good dredgers.\n\nBut between them devourers and nasty elementals formin' from all that wild muck, I can't get close enough to feed it!\n\nHelp me out and throw some of that filthy rubble into the pool, yeah?", objectives = "Throw 6 Filthy Rubble into the muck pool.", completion = "I can smell it from here.\n\n<Rendle inhales deeply and sighs.>\n\nHome sweet home." }
WordHunterWoW_QuestEN[62194] = { title = "Fighting Words", description = "Throughout the Shadowlands, there is so much magic to learn!\n\nA threat in Bastion has put many of their ancient teachings in danger. I wish to study their scrolls before they are lost forever. We must travel there and safeguard what we can!\n\nHelp me fight back the Forsworn at the Temple of Humility and save the scrolls within.", objectives = "Help Sabrina collect 8 Ancient Teachings and eliminate 8 Forsworn enemies.", completion = "You have helped strengthen our forces, Maw Walker." }
WordHunterWoW_QuestEN[62195] = { title = "The Last Word", description = "Inquisitor Darksion was an aspiring practitioner of the arcane arts before Denathrius locked her away.\n\nI've heard she will share her knowledge with anyone that releases her from imprisonment.\n\nI want to learn all she knows! We must free her!", objectives = "Help Sabrina free Inquisitor Darksion.", progress = "Did we find anything good?", completion = "You have helped strengthen our forces, Maw Walker." }
WordHunterWoW_QuestEN[62200] = { title = "Functioning Anima Core", description = "<The incomprehensible core whirs with a pleasant hum. \n\nSurely someone would have a use for this? >", objectives = "Deliver the Functioning Anima Core to Kalisthene.", completion = "Thank you for this, <name>. We must conserve all the anima we can." }
WordHunterWoW_QuestEN[62203] = { title = "Major Mirror Disruptions", description = "", objectives = "" }
WordHunterWoW_QuestEN[62204] = { title = "Major Mirror Disruptions", description = "", objectives = "" }
WordHunterWoW_QuestEN[62205] = { title = "Venthyr Ettiquette", description = "Is that Theotar's new book?", objectives = "Is that Theotar's new book?", progress = "Is that Theotar's new book?", completion = "You know, I really like that Theotar, he knows his stuff and is nice to us even though at times he assumes we can read minds. Silly Venthyr." }
WordHunterWoW_QuestEN[62206] = { title = "Ardenweald Etiquette", description = "Ooh, I am beginning to like these books.", objectives = "Ooh, I am beginning to like these books.", progress = "Ooh, I am beginning to like these books.", completion = "This one looks fun, I like reading about dreams, and it has pictures!" }
WordHunterWoW_QuestEN[62207] = { title = "Bastion Etiquette", description = "That looks like a 'big' book.", objectives = "That looks like a 'big' book.", progress = "That looks like a 'big' book.", completion = "This seems pretty strict, I am surprised that they come to parties, I think it says here that might not be allowed. Well, I will make sure I memorize it word for word, I am sure they will have already." }
WordHunterWoW_QuestEN[62208] = { title = "Maldraxxi Protocols", description = "It looks shorter than the others, but... are those bullets?", objectives = "It looks shorter than the others, but... are those bullets?", progress = "It looks shorter than the others, but... are those bullets?", completion = "Not going to lie to you, this sounds really dry. Do I at least get to wear their cool armor?" }
WordHunterWoW_QuestEN[62209] = { title = "Houndmaster Vasanok", description = "", objectives = "" }
WordHunterWoW_QuestEN[62210] = { title = "Sanngror the Torturer", description = "", objectives = "" }
WordHunterWoW_QuestEN[62211] = { title = "Skittering Broodmother", description = "", objectives = "" }
WordHunterWoW_QuestEN[62213] = { title = "A Brokered Deal", description = "Hey, {name}. I've found a lucrative business proposition that'll help me... us... greatly! See, Au'narim is willing to give us supplies if we can help him recover from a trade deal that went sideways.\n\nApparently, several of his cohorts never returned from a job. He needs us to follow their path and recover the item they failed to deliver. Simple, right?\n\nTo ensure we don't have any mishaps, I've taken the liberty of acquiring a few items that may be of help to us.\n\nSo, you in?", objectives = "Recover the Broker Bauble.", progress = "Did you find the item in question?", completion = "I knew the Maw Walker would deliver." }
WordHunterWoW_QuestEN[62214] = { title = "Forces of Perdition", description = "Survival requires that we keep our enemies in check, Maw Walker.\n\nWith Gorgoa overflowing, the Mawsworn continue to gain strength.\n\nPerdition Hold has been fortified with fresh troops. We cannot allow the Mawsworn to bolster their ranks any further.\n\nMake your way into Perdition Hold and decimate their forces. When the work is done, you may return to me for your reward.", objectives = "Kill Mawsworn Troops within Perdition Hold in The Maw.\n\nSuggested Players [3]", progress = "I trust the Mawsworn did not trouble you?", completion = "A small victory, Maw Walker. Many more will be required." }
WordHunterWoW_QuestEN[62216] = { title = "Training Program", description = "Sergeant Krashj is an adequate drill master, but these recruits need proper training with a real warrior. Someone who has been bloodied on the battlefield. Someone like me!\n\nAnd I know just the fight that will whip these troops into shape.\n\nLet's go teach them a thing or three.", objectives = "Slay Decadious.", completion = "You two make quite the team. It's good to have dependable comrades in arms." }
WordHunterWoW_QuestEN[62217] = { title = "Field Training", description = "Though it was not by our hand, Maldraxxus has dealt a great injustice to the kyrian of Bastion. We must do all that we can to make amends.\n\nThe Forsworn menace continues to be a thorn in their side. Sounds like the perfect opportunity to both show our support and for our recruits to gain some combat experience.", objectives = "Eliminate 15 Forsworn forces at The Eternal Forge in Bastion.", completion = "You and Marz work well together. He'll take the hit whenever you need him to." }
WordHunterWoW_QuestEN[62218] = { title = "A Fountain for Fae", description = "Nuuminuuru spends their days protecting and taking care of many faeries throughout Ardenweald. They have expressed concern about some faeries in their care whom they have not seen in some time.\n\nReport to Nuuminuuru and see if you can help them find their scattered sprites.", objectives = "Report to Nuuminuuru in Glitterfall Basin in Ardenweald.", progress = "A greeting to you, ally of the soulbearers.", completion = "A faerie fountain for a rare relaxation... an enticing incentive indeed." }
WordHunterWoW_QuestEN[62219] = { title = "Fanciful Distractions", description = "Ever chasing their fleets of fancy, my faerie friends are seldom seen.\n\nTheir mercurial natures oft lead them astray, tracing them paths to distraction and dismay.\n\nSeek my friends, insist they return to my roots, and both you and they may receive recompense.", objectives = "Find Riverblossom, Lunarwind, and Flitterfly and convince them to return to Nuuminuuru.", progress = "My wards know to return to my roost, to spin stories of their pursuits and strengthen their spirits.\n\nThe longer they flit away, the deeper the creases of my concern grow.", completion = "The waters of your realm revitalize my wards in ways those of our home cannot.\n\nOnce again, they return to rest." }
WordHunterWoW_QuestEN[62221] = { title = "My Own Death Pony!", description = "That is such a beautiful death pony, ever since I saw my first one I have dreamed of ...", objectives = "That is such a beautiful death pony, ever since I saw my first one I have dreamed of...", progress = "That is such a beautiful death pony, ever since I saw my first one I have dreamed of ...", completion = "<Your butler is nearly in tears.>\n\nI get my own death pony to ride? You are the best mortal I have ever met!" }
WordHunterWoW_QuestEN[62222] = { title = "On Silver Wings", description = "What do you intend for me to do with that thing?", objectives = "What do you intend for me to do with that thing?", progress = "What do you intend for me to do with that thing?", completion = "<Your butler is in shock after you tell him he will be flying.>\n\nIf you really need me to follow you around in the air... of course I will do that... please not too high..." }
WordHunterWoW_QuestEN[62223] = { title = "Ascension Calling: Mikanikos", description = "<While this scroll mimics Kleia's invitation to the Path of Ascension, it is very clearly written in Sika's hand.\n\nIt details an invitation for Mikanikos to participate in the Path, along with Bron.\n\nPerhaps you should bring this to Mikanikos.>", objectives = "Inform Mikanikos he is now able to participate in the Path of Ascension.", completion = "Me? Take part in the Path of Ascension? What a surprise!\n\nBron and I will participate, of course. The leaps we can achieve in centurion development... Imagine!" }
WordHunterWoW_QuestEN[62224] = { title = "A Thread Of Hope", description = "The Court of Night is akin to a thirsty flower, it quickly draws up its nutrients. If well supplied it will bloom and if its supply is depleted, it withers.\n\nOur roots are beginning to dry, we need more anima!\n\nI've sent workers out to place silk lined catchers along the roads and paths that cross Ardenweald. These catchers will collect a tiny bit of anima, not much but enough for what we need.\n\nSeek them out and return the Anima Infused Silk to us.", objectives = "Collect 13 Anima Infused Silk", progress = "Were you able to find the silk?", completion = "Well done. Our leaves lift to the sky in thanks." }
WordHunterWoW_QuestEN[62225] = { title = "Bursting the Bubble", description = "<The words of the shadowy herald are dark and foreboding. Whatever \"the Banished One\" intends to accomplish, it must not come to pass.\n\nSomething foul bubbles within the cauldrons nearby. Judging by the care with which the cultists are tending to them, their contents must be crucial to their plans.\n\nSeveral barrels containing what appears to be a new type of plague have been left unattended. Perhaps they can serve as instruments for sabotage.>", objectives = "Sabotage 3 of the Cult of the Damned's experiments in Mord'rethar.", progress = "What have you discovered?", completion = "Thank the Light, you have returned unharmed!\n\nWere you able to learn anything about what the cult is doing?" }
WordHunterWoW_QuestEN[62226] = { title = "Talethi's Desire", description = "", objectives = "" }
WordHunterWoW_QuestEN[62227] = { title = "Xertora's Construct", description = "", objectives = "" }
WordHunterWoW_QuestEN[62229] = { title = "Ashraka's Intelligence", description = "", objectives = "" }
WordHunterWoW_QuestEN[62230] = { title = "A Stolen Stone Fiend", description = "", objectives = "" }
WordHunterWoW_QuestEN[62231] = { title = "Velkein's Blade", description = "", objectives = "" }
WordHunterWoW_QuestEN[62232] = { title = "Arboreal Tactics", description = "The spriggan of Ardenweald have always been a nuisance. But under Mueh'zala's influence, they could grow into a threat that looms over all of the Shadowlands.\n\nLet's test these troops against a real opponent.", objectives = "Eliminate 12 Bristlecone Spriggan in Mistveil Tangle in Ardenweald.", completion = "I see you and Marz have been busy. Job well done, both of you." }
WordHunterWoW_QuestEN[62234] = { title = "Power of the Colossus", description = "I have another task for you, Maw Walker.\n\nDeep within Perdition Hold, there lurks a menacing mechanization known as the Soulsteel Colossus. It must be destroyed before it wreaks havoc upon us.\n\nTravel to the Hold, and then across the bridge into the Altar of Domination. There, casting its vast shadow upon The Maw, you will find the Soulsteel Colossus.\n\nShatter the colossus and bring me its power source as proof of your victory.", objectives = "Retrieve a Colossal Power Core from Perdition Hold in The Maw.\n\nSuggested Players [3]", progress = "The power source... I trust it was not too heavy?", completion = "The souls trapped within the power core may yet be saved. Leave me to my research, Maw Walker." }
WordHunterWoW_QuestEN[62235] = { title = "Allay Their Fears", description = "", objectives = "" }
WordHunterWoW_QuestEN[62236] = { title = "Rattlebag's Lost Armor", description = "", objectives = "" }
WordHunterWoW_QuestEN[62237] = { title = "Mysterious Soul Mirror", description = "<A shimmering soul mirror draws your attention on Devos's corpse.\n\nPeculiar that she would keep one on her person. Perhaps Thenios will want to see this.>", objectives = "Bring the Mysterious Soul Mirror to Thenios at the temple in the Eonian Archives.", progress = "How can I be of service?", completion = "<Thenios studies the mirror closely.>\n\nI see." }
WordHunterWoW_QuestEN[62238] = { title = "Soul Led Astray", description = "Uther was a being of justice on your world. I am sure it was quite surprising for you to see his fate here, following a leader who embodies what he stood against in life.\n\nI believe you should witness this memory firsthand. Take it to my soul mirror. View the memories within.", objectives = "Use the Soul Mirror at the Eonian Archives to view Uther's arrival in Bastion.", progress = "Sometimes the hard truths are the most important to witness.", completion = "I hope that this memory helps you to understand Uther's path." }
WordHunterWoW_QuestEN[62239] = { title = "Rodent Removal", description = "<The weapon buzzes with a dark, static energy. Whatever this Mawsworn was testing, it appears to have been somewhat successful on the nearby rodents.\n\nFurther investigation may yield additional information.>", objectives = "Test the Tormentor's Rod on 8 Giant Mawrats in The Beastwarrens.", completion = "Serves them right for leaving this unattended.\n\nI am sure we can find other uses for it." }
WordHunterWoW_QuestEN[62241] = { title = "Training Regimen", description = "", objectives = "" }
WordHunterWoW_QuestEN[62244] = { title = "Digging Around", description = "The thin pale ones of Revendreth have been hoarding anima. \n\nI've heard they've been hiding it away, digging holes in the woods and just leaving it there. Anyone could come along and take it.\n\nI say that should be us!\n\nLet's go get some anima.", objectives = "Collect 15 Lost Anima Caches.", completion = "Thank you for the supplies. I'll see about setting some aside for you at regular intervals." }
WordHunterWoW_QuestEN[62245] = { title = "Venari Rep Token Tracking", description = "", objectives = "" }
WordHunterWoW_QuestEN[62246] = { title = "A Fallen Friend", description = "A bracelet delicately woven with living vines falls from Vivanna's wrist as she is slain. In the vines is written, \n\n\"Until Winter's end.\n\n-Flwngyrr\"", objectives = "Return this bracelet to Flwngyrr at the Heart of the Forest\n\nProvided item:", completion = "<They take the bracelet from your hand. A minute passes before they speak again.>\n\nHer favorite was Azurebloom Tea.\n\nThank you for bringing this to me." }
WordHunterWoW_QuestEN[62248] = { title = "Venari Rep Token Tracking", description = "", objectives = "" }
WordHunterWoW_QuestEN[62249] = { title = "Venari Rep Token Tracking", description = "", objectives = "" }
WordHunterWoW_QuestEN[62250] = { title = "A New Adventure Awaits", description = "{name}! You're needed in the present. Things have... well, you should just come back to see.\n\nI would finish what you're doing then head back. I can't keep you in the past for much longer!", objectives = "Return to Stormwind to embark on a new adventure. Chromie's magic will run out when you reach level 70, returning you to Stormwind.", completion = "Welcome back to the present! There's a lot you have to do." }
WordHunterWoW_QuestEN[62256] = { title = "Asset Extraction", description = "Hey, it's my good pal {name}! Listen, I'm in a bit of a bind here. I've been trying to negotiate a deal with the broker Au'larrynar and he needs a little something, a job done before he'll accept.\n\nThe deal is he had an associate who went missing with a rare item. He's asked that I... we... locate and return the missing property.\n\nThe associate was last seen in Ardenweald. I know, strange place, way too bright for me. But, I... we... really need this deal to go through! \n\nSo, you ready to go?", objectives = "Travel to Ardenweald, locate Tabithia, and recover the Otherworldly Egg.", progress = "I trust you have held up to your part of the deal?", completion = "Ah, now this is exquisite. Your reconstructed companion said you would be able to come through and you've done so magnificently!\n\nLet him know I'll count this toward the repayment of his debts." }
WordHunterWoW_QuestEN[62258] = { title = "Soaring Over Bastion", description = "", objectives = "" }
WordHunterWoW_QuestEN[62259] = { title = "Anima-Laden Dreamcatcher", description = "You stumble upon an enchanted dreamcatcher, placed so remotely that it has managed to collect a significant amount of anima without being harvested. Droman Dawnblossom in nearby Dreamsong Fenn would surely appreciate its safe return.", objectives = "Return the Enchanted Dreamcatcher to Droman Dawnblossom in Dreamsong Fenn.\n\nProvided item:", completion = "Oh my! How did that get there? No matter. This anima will nurture many souls. Thank you, traveler!" }
WordHunterWoW_QuestEN[62261] = { title = "Grinder", description = "It's tough keeping these hands of mine razor sharp. With all the hacking and cleaving, they can grow dull so quickly! What's a girl to do?\n\nThe House of the Chosen makes some very fine quality sharpening stones. I doubt they will just hand them over, but I'm sure my blades can persuade them otherwise.\n\nHow about we pay them a visit and see how many stones they can spare?", objectives = "Collect 12 Sharpening Stones and 3 Bonesheared Grinders.", progress = "Did you kill them all?", completion = "I see Guillotine's \"negotiations\" were successful.\n\nThank you, Maw Walker. These sharpening stones will be useful." }
WordHunterWoW_QuestEN[62262] = { title = "Fungal Feeding", description = "Just as I was making progress on our alternative defense research, my spore samples ran dry!\n\nThe mushrooms I was using can only be found in a particularly unpleasant location to the southeast. To collect an appropriately sized sample, you'll have to--how do I put this--feed them. \n\nDon't ask me why, but apparently, they mature fastest with a nice, rotting corpse nearby.\n\nTry luring a few undead to our fungal friends. That should give 'em all the nutrients they need to grow big and strong.", objectives = "Collect 20 Mature Spore Samples from Gloomshrooms in Scourgeholme.", progress = "Any luck with those samples?", completion = "Oh, these are just lovely!\n\nI hope you didn't get your hands too dirty." }
WordHunterWoW_QuestEN[62263] = { title = "Go Beyond!", description = "Ah, you're just in time. I've made quite the discovery.\n\nI've managed to make a connection even further out than I ever have before.\n\nHow did I do it, you ask? Hard work, that's how! But you knew that. You're almost as hardworking as I am. That's what you're here for!\n\nUp for an even more exciting adventure?", objectives = "Investigate the unknown area.", progress = "I feel a breeze on the other side. I guess that means it's not underground.", completion = "Must be nice to have the leisure to just sit and think all the time. \n\nI've barely got time myself, with all the work I have keeping this place together!\n\nStill, that was nice of you to help out the old turtle." }
WordHunterWoW_QuestEN[62265] = { title = "A New Adventure Awaits", description = "{name}! You're needed in the present. Things have... well, you should just come back to see.\n\nI would finish what you're doing then head back. I can't keep you in the past for much longer!", objectives = "Return to Orgrimmar to embark on a new adventure. Chromie's magic will run out when you reach level 70, returning you to Orgrimmar.", completion = "Welcome back to the present! There's a lot you have to do." }
WordHunterWoW_QuestEN[62275] = { title = "Bastion", description = "After being set back by a surprise attack by Maldraxxus forces and an army of their own fallen kin known as the Forsworn, the Ascended stand to lose control of Bastion if they are not given aid.", objectives = "Speak with Tal-Inara.", completion = "Bastion is in dire need of your aid." }
WordHunterWoW_QuestEN[62276] = { title = "Drink to the Dead", description = "The Forsworn are ravaging the temples of Bastion, and the aspirants are leaving behind their supplies as they flee.\n\nAll those wonderful bottles of nectar falling into the hands of the Forsworn? I think not! \n\nThere's no way we can save all of the aspirants, but we can keep the Forsworn from taking those supplies. Besides... we could all use something to drink around here.", objectives = "24 Purified Nectar and 2 Stewards collected", progress = "Did you find us some supplies?", completion = "Uh, I see you brought back a few friends?" }
WordHunterWoW_QuestEN[62277] = { title = "Ardenweald", description = "Ardenweald still faces threats from the Drust, as well as other nefarious forces.\n\nThe Winter Queen could use your aid in fending off the forces that seek to destroy Ardenweald.", objectives = "Speak with Tal-Inara.", completion = "Ardenweald would be most appreciative of your help." }
WordHunterWoW_QuestEN[62278] = { title = "Maldraxxus", description = "With the houses in shambles, the loyal army of the Primus struggles to hold their ground in Maldraxxus.\n\nThey need help to tip the scales in their favor.", objectives = "Speak with Tal-Inara.", completion = "The armies loyal to the Primus need your aid." }
WordHunterWoW_QuestEN[62279] = { title = "Revendreth", description = "Chaos rules Revendreth in the wake of Sire Denathrius's betrayal. \n\nThey are in dire need of your aid!", objectives = "Speak with Tal-Inara.", completion = "Revendreth would be most grateful for your aid." }
WordHunterWoW_QuestEN[62280] = { title = "Limbo", description = "", objectives = "" }
WordHunterWoW_QuestEN[62284] = { title = "Observing Battle", description = "It is clear that you mortals thrive on conflict. Members of my cartel have a keen interest in observing your combat prowess in action.\n\nYou seem to be fond of squabbling over contested ground. Observing such territorial behavior would benefit me, and could provide opportunities for you as well.\n\nCan I count on your participation?", objectives = "Obtain Honor in Random Battlegrounds.", progress = "Observation in progress.", completion = "Excellent. You fight so fiercely to claim a piece of ground. The Observer will find that intriguing." }
WordHunterWoW_QuestEN[62285] = { title = "Observing War", description = "Your appetite for conflict is a subject of much discussion here in Oribos, mortal. Members of my cartel have a keen interest in observing your combat prowess in action.\n\nThough I understand a great war recently concluded on your world, I am told large-scale conflicts continue to play out in certain locations.\n\nAny chance you could arrange a demonstration?", objectives = "Obtain Honor in Epic Battlegrounds.", progress = "Observation in progress.", completion = "A most enlightening conflict. The Observer will be pleased." }
WordHunterWoW_QuestEN[62286] = { title = "Observing Skirmishes", description = "Fascinating how much entertainment your kind draws from conflict, mortal. Members of my cartel have a keen interest in observing your combat prowess in action.\n\nI am told that small-scale skirmishes allow your greatest champions to demonstrate their martial superiority over their rivals. No doubt my people would learn much from observing such a contest.\n\nMight I have the honor of a demonstration?", objectives = "Obtain Honor from Arena Skirmishes.", progress = "Observation in progress.", completion = "Fascinating. Fascinating indeed. The Observer will be pleased." }
WordHunterWoW_QuestEN[62287] = { title = "Observing Arenas", description = "The denizens of your world seem to thrive on conflict, mortal. Members of my cartel have a keen interest in observing your combat prowess in action.\n\nSmall-scale encounters in a constrained setting could prove informative for me, and potentially lucrative for you.\n\nWhat do you say?", objectives = "Obtain Honor in Arenas.", progress = "Observation in progress.", completion = "I do so enjoy the completion of a successful arrangement! The Observer will be pleased." }
WordHunterWoW_QuestEN[62288] = { title = "Observing Teamwork", description = "It's truly fascinating how conflict drives your kind, mortal. Members of my cartel have a keen interest in observing your combat prowess in action.\n\nI am told that some of your most impressive martial demonstrations involve combat between predetermined teams. My people are unfamiliar with such contests.\n\nWould you be willing to offer a demonstration?", objectives = "Obtain Honor in Rated Battlegrounds.", progress = "Observation in progress.", completion = "Our arrangement allowed me to gather some very useful information. The Observer will be pleased." }
WordHunterWoW_QuestEN[62289] = { title = "Observing Conflict", description = "Your kind seems to lead an inherently contentious existence, mortal. Members of my cartel have a keen interest in observing your combat prowess in action.\n\nIt is apparent that conflicts between you and your rivals can break out anywhere, even in the realms of Death. Much could be learned from observing such engagements.\n\nCan I count on your participation?", objectives = "" }
WordHunterWoW_QuestEN[62291] = { title = "Venari Rep Token Tracking", description = "", objectives = "" }
WordHunterWoW_QuestEN[62292] = { title = "Pitch Black Scourgestones", description = "", objectives = "The most powerful of the undead carry scourgestones imbued with the darkest magic. \n\nWe do not know from whence they came, but their power is unlike any we have encountered before. \n\nPlease relinquish any you find to the Argent Crusade. Who knows what foul evil may be lurking within them?", progress = "The most powerful of the undead carry scourgestones imbued with the darkest magic. \n\nWe do not know from whence they came, but their power is unlike any we have encountered before. \n\nPlease relinquish any you find to the Argent Crusade. Who knows what foul evil may be lurking within them?", completion = "We will study these stones at once and seal them away. They bring me unease." }
WordHunterWoW_QuestEN[62293] = { title = "Darkened Scourgestones", description = "", objectives = "Scourgestones were once common amongst the minions of the Lich King. But these new ones are different... and darker.\n\nBring them to us as you find them. They will serve both a mark of your victories, and as an opportunity for us to study their strange magic.", progress = "Scourgestones were once common amongst the minions of the Lich King. But these new ones are different... and darker.\n\nBring them to us as you find them. They will serve both a mark of your victories, and as an opportunity for us to study their strange magic.", completion = "We prevailed against the undead before, and we shall do so again! For the Light!" }
WordHunterWoW_QuestEN[62294] = { title = "One Lich's Trash...", description = "It is said that one person's trash, is another's treasure. When it comes to relics, the adage is particularly true.\n\nThe House of Rituals is notoriously secretive, which means any knowledge we can glean from them will be all the sweeter.\n\nIf we sift through their detritus, I'm sure there are all sorts of treasures we will find.", objectives = "Search through Piles of Debris within the House of Rituals for clues about its past, and recover an Intriguing Ancient Relic.", progress = "Did you find anything of interest?", completion = "This is simply marvelous! This will provide some excellent insight into the history of Margrave Sin'dane... and possibly something we can use to our own benefit later on." }
WordHunterWoW_QuestEN[62295] = { title = "Cleaning Out the Vault", description = "The Scourge's rampant aggression has proven difficult to predict, even for us.\n\nBy the time we knew they were upon us, it was too late.\n\nWith our forces spread thin, we are left with what you see before you.\n\nEnter the vault. Slay our enemies where they stand.\n\nSoon the Shadow Vault will be ours once more.", objectives = "Purge the Shadow Vault of the Scourge presence." }
WordHunterWoW_QuestEN[62296] = { title = "Into the Unknown", description = "Come to pay old Marasmius a visit? I have a special task for you.\n\nOne of my shoots has found a strange place, a place even I've never seen before.\n\nI'm not entirely sure what's in there or if it's even safe. But that's what my trusty mushroomancers are for!\n\nWhat do you say, {name}? Up for an adventure?", objectives = "Investigate the unknown area.", progress = "Keep your guard up. It could lead anywhere!", completion = "That was close. Those pests can quickly blast away whole chunks of Ardenweald if we aren't careful. We've got enough problems on our hands as it is!" }
WordHunterWoW_QuestEN[62297] = { title = "A Fatal Failure", description = "Acolyte, we could use a hand here!\n\nIt seems one of your fellow pupils botched their ritual in spectacular fashion. Now destructive necromantic energies are running rampant throughout the house.\n\nThis threat must be dealt with. Can you assist?", objectives = "Kill 7 Fatal Coalescences in the House of Rituals.", progress = "Have you taken care of the threat, acolyte?", completion = "Well done, acolyte. The rest should dissipate with time.\n\nTake this, it was left behind by the feckless adept that created this mess. I hope you will put it to better use." }
