WordHunterWoW_QuestEN[62308] = { title = "Mantle of Mastery", description = "You have done much to establish yourself as a promising acolyte. Your superiors have made it known that you are ready to be tested for your ritualist's mantle. \n\nWhen you are ready, begin the Ritual of Ancient Summoning to call forth an elder spirit of Maldraxxus. Conquer the spirit, and prove your mettle!", objectives = "Summon an elder spirit of Maldraxxus through the Prime Arcanum and defeat it. Summoning requires three players.", completion = "You have proven yourself worthy to don the mantle, acolyte.\n\nWear it with honor and pride." }
WordHunterWoW_QuestEN[62309] = { title = "Adventurer: Secutor Mevix", description = "", objectives = "<name>, it is good to see you again!\n\nFollowing your success against the House of Constructs, Secutor Mevix is eager for more action on the battlefield.\n\nDon't leave an eager soldier to wallow here. Give him purpose!" }
WordHunterWoW_QuestEN[62312] = { title = "Adventurer: Gunn Gorgebone", description = "", objectives = "We've got an exciting development today, <name>!\n\nYou must have made quite an impression. Gunn Gorgebone, one of the champions of the Theater of Pain, is demanding to join our ranks here. Demanding it!" }
WordHunterWoW_QuestEN[62313] = { title = "Adventurer: Rencissa the Dynamo", description = "", objectives = "<name>! Step closer, come, come!\n\nI've just received word that none other than Rencissa the Dynamo is on her way here to fight for you. Rencissa! The Dynamo!\n\nWho should we have her kill first?" }
WordHunterWoW_QuestEN[62314] = { title = "Adventurer: Khaliiq", description = "", objectives = "Listen up, <name>. We need more eyes out there on the battlefield.\n\nThere's too many threats, and not enough information flowing our way.\n\nSee if Khaliiq is up to the task. You heard me right, I said more Eyes!" }
WordHunterWoW_QuestEN[62315] = { title = "Adventurer: Plaguey", description = "", objectives = "We've got a strange one today, <name>.\n\nMarileth stopped by to say that his slime Plaguey is feeling more blue than usual, and asked if we could keep him entertained.\n\nWhat does this look like, a kennel? Plaguey can earn his keep like the rest of us! Get him out there, soldier!" }
WordHunterWoW_QuestEN[62316] = { title = "Adventurer: Rathan", description = "", objectives = "Your dedication to Maldraxxus is inspiring, <name>.\n\nRathan has requested to join our ranks here at the Seat, for the good of Maldraxxus. His expertise will be a welcome addition!\n\nI suspect he wants to keep an eye on Emeni as well, but you didn't hear that from me." }
WordHunterWoW_QuestEN[62317] = { title = "Casting Doubt", description = "<A note has been left here for Kel'Thuzad. It does not appear that he has read it.>\n\nBaron, I do not trust your new favorite acolyte. Something has been off about them ever since they returned from their ritual with the Kyrian remains.\n\nYour work is too important to allow such discrepancies. The acolyte should be disposed of.\n\nFaithfully,\n\nSorcerer Vutral", objectives = "Defeat Sorcerer Vutral in the Vault of Souls." }
WordHunterWoW_QuestEN[62320] = { title = "Regalia de Rigueur", description = "Ah, if it isn't Kel'Thuzad's favorite acolyte? I simply cannot understand how a baron like him would surround himself with such... homely company.\n\nWhen was the last time you even chanced at a looking glass? Those faded robes do your station no justice.\n\nI would take it upon myself to update your drab apparel, if I weren't sufferring such a shortage on the house's preferred amethystine tint.\n\nYou could always fetch some yourself. The sorcerers usually have some stashed among their tomes and altars.", objectives = "Collect 10 Amethystine Powder from the House of Rituals.", progress = "I will need large quantities of amethystine powder if I am to fix...\n\n<Moret gestures at you broadly.>\n\n...this.", completion = "It brings me great relief that your pallid vestments will no longer offend my vision.\n\nDo try keep them in better repair henceforth." }
